let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function safeUrl(url,images=false){if(!url)return '';if(images&&/^drive:/.test(url))return mediaUrl(url);try{const u=new URL(url);if(u.protocol==='https:')return u.href;if(images&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(url)&&url.length<=42000)return url;}catch(_){}return '';}
function normalPhone(value){let s=value.replace(/[\s()+-]/g,'');if(s.startsWith('0'))s='62'+s.slice(1);if(!/^628\d{7,11}$/.test(s))throw Error('Gunakan nomor Indonesia, contoh 081234567890.');return s;}
function contact(){const p=S.settings.whatsapp;if(/^628\d{7,11}$/.test(p||''))window.open('https://wa.me/'+p,'_blank','noopener,noreferrer');else toast('Kontak admin belum diatur. Silakan kembali setelah konfigurasi selesai.');}
// Cache only the public catalog; never persist account or order responses.
const CATALOG_BROWSER_TTL=3*60*1000;
const CATALOG_BROWSER_KEY='jh:public-catalog:v1:'+CONFIG.API_URL;
const CATALOG_WRITES=new Set(['saveProduct','deleteProduct','saveCategory','updateCategory','deleteCategory','savePreview','deletePreview','reorderPreviews','saveSettings']);
let catalogPending=null,catalogEpoch=0;
function validCatalog(data){return !!data&&Array.isArray(data.products)&&Array.isArray(data.categories)&&!!data.settings&&typeof data.settings==='object'&&!Array.isArray(data.settings);}
function clearBrowserCatalog(){
 catalogEpoch++;catalogPending=null;
 try{localStorage.removeItem(CATALOG_BROWSER_KEY);}catch(_){}
}
function readBrowserCatalog(){
 try{
  const entry=JSON.parse(localStorage.getItem(CATALOG_BROWSER_KEY)||'null'),now=Date.now();
  if(entry&&Number.isFinite(entry.savedAt)&&entry.savedAt<=now&&now-entry.savedAt<CATALOG_BROWSER_TTL&&validCatalog(entry.data))return entry.data;
  localStorage.removeItem(CATALOG_BROWSER_KEY);
 }catch(_){}return null;
}
async function api(action,data={}){
 if(action!=='catalog'){
  if(!CATALOG_WRITES.has(action))return apiNetwork_(action,data);
  clearBrowserCatalog();
  try{return await apiNetwork_(action,data);}finally{clearBrowserCatalog();}
 }
 const cached=readBrowserCatalog();if(cached!==null)return cached;
 if(catalogPending)return catalogPending;
 const epoch=catalogEpoch;
 const request=apiNetwork_('catalog',data).then(result=>{
  if(!validCatalog(result))throw Error('Format katalog dari server tidak valid.');
  if(epoch===catalogEpoch){try{localStorage.setItem(CATALOG_BROWSER_KEY,JSON.stringify({savedAt:Date.now(),data:result}));}catch(_){}}
  return result;
 });
 catalogPending=request;
 try{return await request;}finally{if(catalogPending===request)catalogPending=null;}
}
window.addEventListener('storage',event=>{if(event.key===CATALOG_BROWSER_KEY||event.key===null){catalogEpoch++;catalogPending=null;}});
async function apiNetwork_(action,data={}){
 const controller=new AbortController();
 const timer=setTimeout(()=>controller.abort(),30000);
 try{
  const response=await fetch(action==='catalog'?'/api/jasa':'/api/rpc',action==='catalog'?{
   method:'GET',credentials:'omit',signal:controller.signal
  }:{
   method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},
   body:JSON.stringify({...data,action,token:S.token}),signal:controller.signal
  });
  let result;try{result=await response.json();}catch(_){throw Error('Respons API bukan JSON. Periksa deployment dan jalur /api.');}
  if(!response.ok||!result.ok)throw Error(result.error||'Permintaan gagal. Coba lagi.');
  return result.data;
 }catch(error){
  if(error.name==='AbortError')throw Error('Koneksi melewati batas waktu. Untuk checkout, periksa Pesanan Saya sebelum mencoba kembali.');
  throw error;
 }finally{clearTimeout(timer);}
}
function setNotice(){const el=$('#connectionNotice');if(!CONFIG.API_URL)el.innerHTML='<div class="notice"><strong>Mode pratinjau.</strong> Katalog berisi contoh jasa dan harga. Akun, checkout, serta admin aktif setelah backend Vercel dikonfigurasi.</div>';else if(S.loadError)el.innerHTML=`<div class="error">Katalog belum terhubung. ${esc(S.connectionError||'Periksa konfigurasi Google Sheets di Vercel.')} <a href="/api/jasa" target="_blank" rel="noopener noreferrer">Periksa backend</a> <button class="btn small" data-action="reload">Coba lagi</button></div>`;else el.innerHTML='';}
function art(product){const index=Math.max(0,CATEGORIES.indexOf(product.category));const themes=[['#eaf0ff','#244f9e','doc','Laporan','Dokumen rapi'],['#f3eefa','#71508b','slide','Presentasi','Ide jadi visual'],['#e7f2ed','#2d6957','chart','Data & Excel','Lebih terstruktur'],['#fcf0e5','#925d38','pen','Desain','Kesan pertama'],['#e8eff5','#34566c','cad','Teknik','Presisi detail'],['#fff4dc','#82621e','book','Belajar','Pahami konsep']];const t=themes[index];return `<div class="art" aria-hidden="true" style="--art-bg:${t[0]};--art-ink:${t[1]}"><div class="arttype"><small>${t[4]}</small>${t[3]}</div><div class="artpaper">${icon(t[2],45)}</div></div>`;}
function thumb(p){const src=safeUrl(p.thumbnail,true);return `<div class="thumb">${src?`<img src="${esc(src)}" alt="Contoh layanan ${esc(p.title)}" loading="lazy" width="600" height="360" referrerpolicy="no-referrer">`:art(p)}${p.featured?'<span class="badge">Pilihan JASAhub</span>':''}</div>`;}
function topbar(){const el=$('#topactions');el.innerHTML=S.user?`<span class="avatar" aria-hidden="true">${esc(S.user.name.slice(0,1).toUpperCase())}</span><span class="tiny userlabel">${esc(S.user.name)}</span><button class="iconbtn" data-action="logout" aria-label="Keluar akun">${icon('logout')}</button>`:`<button class="btn ghost small" data-action="auth" data-mode="login">Masuk</button><button class="btn primary small" data-action="auth" data-mode="register">Daftar ${icon('arrow',15)}</button>`;$('#adminLink').hidden=S.user?.role!=='admin';}
function card(p){return `<article class="service">${thumb(p)}<div class="servicebody"><div class="cat">${esc(p.category)}</div><h3>${esc(p.title)}</h3><p class="desc">${esc(p.description)}</p><div class="meta"><span>${icon('clock',13)} ${p.days} hari</span><span>${icon('refresh',13)} ${p.revisions} revisi</span></div><div class="cardfoot"><div class="price"><small>Harga paket awal</small><strong>${rupiah(p.price)}</strong></div><button class="btn" data-action="detail" data-id="${esc(p.id)}">Lihat Detail ${icon('arrow',13)}</button></div></div></article>`;}
function catalog(){
 $('#page').innerHTML=`<div class="welcome"><div><h1>${S.user?'Halo, '+esc(S.user.name.split(' ')[0])+'!':'Selamat datang di JASAhub.'}</h1><p>Ada yang perlu dibantu hari ini? Mulai dari sini.</p></div><span class="datepill">${icon('calendar',16)} ${new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span></div>
 <section class="hero" aria-labelledby="heroTitle"><div class="herotext"><span class="badge">SATU HUB, BANYAK SOLUSI</span><h2 id="heroTitle">Urusan menumpuk?<br><span>Ada jasa yang tepat.</span></h2><p>Dari dokumen sampai desain, temukan bantuan untuk membuat pekerjaanmu lebih ringan.</p><button class="btn primary" data-action="explore">Temukan Jasamu ${icon('arrow',17)}</button><div class="herofoot"><span>${icon('check',13)} Harga transparan</span><span>${icon('check',13)} Brief sesuai kebutuhan</span><span>${icon('check',13)} Progres bisa dipantau</span></div></div><div class="heroart" aria-hidden="true"><div class="herodoc"><div class="dochead">${icon('doc',25)}</div><div class="docline"></div><div class="docline short"></div><div class="docchart"><i style="height:25px"></i><i style="height:38px"></i><i style="height:48px"></i></div></div><div class="floatcard"><span class="floaticon">${icon('check',19)}</span><span><strong>Lebih rapi.</strong>Lebih siap dipresentasikan.</span></div><div class="floatcard bottom"><span class="floaticon">${icon('clock',18)}</span><span><strong>Waktumu berharga.</strong>Fokus ke hal yang penting.</span></div></div></section>
 <div class="valuebar"><div class="value"><span class="valueicon">${icon('grid',20)}</span><div><strong>Beragam pilihan jasa</strong><p>Temukan sesuai kebutuhanmu</p></div></div><div class="value"><span class="valueicon">${icon('wallet',20)}</span><div><strong>Tahu harga dari awal</strong><p>Lingkup layanan dijelaskan</p></div></div><div class="value"><span class="valueicon">${icon('shield',20)}</span><div><strong>Pesanan terpantau</strong><p>Lihat status dari akunmu</p></div></div></div>
 <section id="catalogSection" aria-labelledby="catalogTitle"><div class="sectionhead"><div><h2 id="catalogTitle">Temukan jasa pilihanmu</h2><p>Bantuan kecil, dampak besar untuk harimu.</p></div><span class="count" id="serviceCount"></span></div><div class="filters" id="categoryFilters"></div><div class="tools"><label class="searchbox">${icon('search',19)}<input id="search" type="search" placeholder="Cari jasa, misalnya laporan atau desain…" aria-label="Cari jasa" value="${esc(S.search)}"></label><select id="sort" aria-label="Urutkan jasa"><option value="featured">Pilihan JASAhub</option><option value="low">Harga terendah</option><option value="high">Harga tertinggi</option><option value="fast">Pengerjaan tercepat</option></select></div><div class="grid" id="serviceGrid"></div><p class="previewnote">Harga berlaku untuk lingkup paket awal. Baca detail layanan sebelum memesan.</p></section>
 <section class="infocta"><div><h3>Kebutuhanmu lebih spesifik?</h3><p>Konsultasikan lingkup dan estimasi sebelum membuat pesanan.</p></div><button class="btn" data-action="contact">Diskusi dengan Admin ${icon('message',17)}</button></section>`;
 $('#sort').value=S.sort;renderFilters();renderProducts();
}
function renderFilters(){const cats=['Semua Jasa',...S.categories.map(x=>x.name)];$('#categoryFilters').innerHTML=cats.map(c=>`<button class="chip ${S.category===c?'active':''}" aria-pressed="${S.category===c}" data-action="filter" data-name="${esc(c)}">${esc(c)}</button>`).join('');}
function renderProducts(){let list=S.products.filter(p=>(S.category==='Semua Jasa'||p.category===S.category)&&[p.title,p.category,p.description].join(' ').toLowerCase().includes(S.search.toLowerCase()));list.sort((a,b)=>S.sort==='low'?a.price-b.price:S.sort==='high'?b.price-a.price:S.sort==='fast'?a.days-b.days:Number(b.featured)-Number(a.featured));$('#serviceCount').textContent=list.length+' jasa tersedia';$('#serviceGrid').innerHTML=list.map(card).join('')||`<div class="empty">${icon('search',32)}<h3>${S.loadError?'Katalog belum terhubung':'Belum ada jasa yang cocok'}</h3><p>${S.loadError?'Coba muat ulang setelah memeriksa koneksi.':'Coba kata kunci lain atau pilih semua kategori.'}</p><button class="btn" data-action="resetFilters">Reset pencarian</button></div>`;}
function showModal(title,html,narrow=false){const m=$('#modal');if(!m.open)S.returnFocus=document.activeElement;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;m.classList.toggle('narrow',narrow);hydrate();if(!m.open)m.showModal();m.scrollTop=0;const focus=$('input:not([type=hidden]),textarea,select,button', $('#modalBody'));if(focus)focus.focus({preventScroll:true});}
function closeModal(){S.pending=false;$('#modal').close();}
function detail(id){const p=S.products.find(x=>x.id===id);if(!p)return;S.selected=p;showModal('Detail layanan',`${thumb(p)}<span class="cat">${esc(p.category)}</span><h3 style="font-size:24px;margin-top:8px">${esc(p.title)}</h3><p class="detailtext">${esc(p.description)}</p><div class="detailstats"><div><span class="muted">Paket awal</span><strong>${rupiah(p.price)}</strong></div><div><span class="muted">Estimasi</span><strong>${p.days} hari</strong></div><div><span class="muted">Termasuk</span><strong>${p.revisions} revisi</strong></div></div><p class="formhint">Estimasi dimulai setelah pembayaran terverifikasi dan bahan lengkap. Untuk lingkup di luar deskripsi, konsultasi dahulu.</p><div class="formfoot"><button class="btn" data-action="contact">Konsultasi</button><button class="btn primary" data-action="checkout">Checkout ${icon('arrow',17)}</button></div>`);}
function auth(mode='login',pending=false){S.authMode=mode;S.pending=pending;showModal(pending?'Masuk untuk melanjutkan checkout':'Selamat datang di JASAhub',`<div class="authswitch"><button class="${mode==='login'?'active':''}" data-action="authTab" data-mode="login">Masuk</button><button class="${mode==='register'?'active':''}" data-action="authTab" data-mode="register">Daftar</button></div><form id="authForm" class="stack">${mode==='register'?'<label class="field">Nama lengkap<input name="name" autocomplete="name" minlength="2" maxlength="80" required></label>':''}<label class="field">${mode==='register'?'Nomor WhatsApp':'Nomor WhatsApp / Username'}<input type="${mode==='register'?'tel':'text'}" name="phone" autocomplete="username" placeholder="${mode==='register'?'081234567890':'Nomor WhatsApp atau username admin'}" maxlength="80" required><small>${mode==='register'?'Gunakan nomor Indonesia yang aktif.':'Masuk menggunakan nomor WhatsApp atau username admin.'}</small></label><label class="field">Password<span class="pw"><input type="password" name="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="${mode==='register'?6:1}" maxlength="128" required aria-describedby="passwordHint"><button type="button" data-action="togglePassword" aria-label="Tampilkan password">Lihat</button></span><small id="passwordHint">${mode==='register'?'Minimal 6 karakter.':'Masukkan password akunmu.'}</small></label><div class="error" id="authError" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">${mode==='login'?'Masuk':'Buat Akun'} ${icon('arrow',16)}</button></form><p class="formhint">${mode==='register'?'Dengan mendaftar, kamu menyetujui ketentuan layanan dan kebijakan privasi pada halaman bantuan. Nomor belum diverifikasi OTP.':'Kesulitan mengakses akun? Hubungi admin. Pemulihan password otomatis belum tersedia.'}</p><button class="btn ghost small" data-action="contact">Hubungi Admin</button>`,true);}
async function deriveKey(password,salt){if(!crypto.subtle)throw Error('Browser memerlukan HTTPS untuk fitur akun. Gunakan Vercel HTTPS atau localhost.');const bytes=new Uint8Array(salt.match(/.{2}/g).map(x=>parseInt(x,16)));const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes,iterations:210000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits),x=>x.toString(16).padStart(2,'0')).join('');}
function randomHex(){return Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');}
async function authSubmit(form){await formTask(form,'#authError',async()=>{const d=Object.fromEntries(new FormData(form));const phone=S.authMode==='register'?normalPhone(d.phone):d.phone.trim();let passwordKey;if(S.authMode==='login'){const challenge=await api('challenge',{phone});if(challenge.legacy)passwordKey=await deriveKey(d.password,challenge.salt);}const result=await api(S.authMode,{phone,name:d.name,password:d.password,passwordKey});S.token=result.token;S.user=result.user;persistSessionToken(S.token);topbar();if(S.pending&&S.selected){S.pending=false;checkout();}else{$('#modal').close();await route();}toast('Berhasil masuk. Selamat datang!');});}
function localDate(date){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);}
function checkout(){if(!S.selected)return;if(!CONFIG.API_URL){toast('Checkout aktif setelah API_URL terhubung ke Apps Script.');return;}if(!S.user){auth('login',true);return;}const p=S.selected;const min=localDate(new Date(Date.now()+p.days*86400000));showModal('Lengkapi pesananmu',`<div class="checkoutsummary"><span class="eyebrow muted">LAYANAN PILIHAN</span><h3>${esc(p.title)}</h3><div class="row spread"><span class="muted tiny">${p.days} hari · ${p.revisions} revisi</span><strong>${rupiah(p.price)}</strong></div></div><form id="checkoutForm" class="stack" data-request="${randomHex()}"><label class="field">Ceritakan kebutuhanmu<textarea name="brief" minlength="15" maxlength="5000" required placeholder="Tujuan, jumlah halaman/slide, format hasil, dan arahan khusus…"></textarea></label><label class="field">Tautan bahan (opsional)<input type="url" name="materialUrl" placeholder="https://drive.google.com/…" maxlength="2000"><small>Gunakan HTTPS. Berikan akses hanya kepada pihak yang diperlukan.</small></label><label class="field">Deadline yang diharapkan<input type="date" name="deadline" min="${min}" required><small>Paling cepat ${esc(min)}. Jadwal dikonfirmasi setelah bahan dan pembayaran lengkap.</small></label><label class="check"><input type="checkbox" required> Saya sudah membaca lingkup layanan dan ketentuan pemesanan.</label><div id="checkoutError" class="error" role="alert" tabindex="-1"></div><div class="formfoot"><button class="btn" type="button" data-action="detail" data-id="${esc(p.id)}">Kembali</button><button class="btn primary" type="submit">Buat Pesanan ${icon('arrow',17)}</button></div><p class="formhint">Pembayaran diverifikasi manual oleh admin. Kamu akan menerima nomor pesanan dan instruksi pembayaran.</p></form>`);}
async function formTask(form,errorSelector,fn){const button=$('button[type=submit]',form);const prev=button.innerHTML;const error=$(errorSelector);error.textContent='';button.disabled=true;button.textContent='Memproses…';try{await fn();}catch(e){if(error.isConnected){error.textContent=e.message;error.focus();}else toast(e.message);}finally{if(button.isConnected){button.disabled=false;button.innerHTML=prev;}}}
function busy(){return '<div class="busy" role="status"><span class="spin" aria-hidden="true"></span> Memuat data terbaru…</div>';}
async function ordersPage(version){if(!S.user){$('#page').innerHTML=`<div class="empty">${icon('bag',38)}<h1 style="font-size:24px;margin:16px 0">Pesananmu, dalam satu tempat.</h1><p>Masuk untuk melihat progres, pembayaran, dan hasil pengerjaan.</p><button class="btn primary" data-action="auth" data-mode="login">Masuk ke Akun</button></div>`;return;}$('#page').innerHTML=busy();try{const orders=await api('orders');if(version!==S.routeVersion)return;$('#page').innerHTML=`<div class="sectionhead"><div><h1 style="font-size:25px">Pesanan Saya</h1><p>Pantau pengerjaan dan akses hasil layananmu.</p></div><button class="btn small" data-action="refresh">${icon('refresh',16)} Muat ulang</button></div><div class="stack">${orders.length?orders.map(orderCard).join(''):'<div class="empty"><h3>Belum ada pesanan</h3><p>Mulai dengan memilih layanan yang kamu butuhkan.</p><a href="#catalog" class="btn primary">Jelajahi Jasa</a></div>'}</div><div class="panel" style="margin:24px 0"><h2 style="font-size:18px;margin-bottom:10px">Informasi pembayaran</h2><p class="detailtext">${esc(S.settings.paymentInfo||'Hubungi admin untuk instruksi pembayaran.')}</p><p class="tiny muted">Pembayaran dikonfirmasi manual. Jangan membayar jika instruksi belum jelas.</p></div>`;}catch(e){if(version===S.routeVersion)pageError(e);}}
function legacyOrderCard(o){const idx=['Menunggu Konfirmasi','Dikonfirmasi','Diproses','Review Pelanggan','Selesai'].indexOf(o.status);const result=safeUrl(o.resultUrl);const material=safeUrl(o.materialUrl);return `<article class="ordercard"><div class="row spread wrap"><span class="tiny muted">${esc(o.id)}</span><div class="row wrap"><span class="badge">${esc(o.status)}</span><span class="badge ${o.paymentStatus==='Lunas'?'green':'orange'}">${esc(o.paymentStatus)}</span></div></div><h3>${esc(o.title)}</h3><div class="statusrail" aria-hidden="true">${[0,1,2,3,4].map(n=>`<span class="${n<=idx?'done':''}"></span>`).join('')}</div><div class="orderbody"><div><span class="label">Kebutuhan</span><p>${esc(o.brief)}</p>${material?`<a class="tiny" href="${esc(material)}" target="_blank" rel="noopener noreferrer">Buka bahan ${icon('arrow',13)}</a>`:''}${o.adminNote?`<div style="margin-top:15px"><span class="label">Catatan admin</span><p>${esc(o.adminNote)}</p></div>`:''}</div><div><span class="label">Detail pesanan</span><p>Total: <strong>${rupiah(o.price)}</strong></p><p>Deadline: ${esc(o.deadline)}</p><p>Sisa revisi: ${Number(o.revisions)}</p><p class="tiny muted">Dibuat ${new Date(o.createdAt).toLocaleDateString('id-ID')}</p>${o.paymentReference?`<p class="tiny">Referensi bayar: ${esc(o.paymentReference)}</p>`:''}</div></div><div class="orderactions">${o.paymentStatus!=='Lunas'&&o.status!=='Dibatalkan'?`<button class="btn small" data-action="pay" data-id="${esc(o.id)}">${icon('wallet',16)} Konfirmasi Pembayaran</button>`:''}${result?`<a class="btn primary small" href="${esc(result)}" target="_blank" rel="noopener noreferrer">Buka Hasil ${icon('arrow',15)}</a>`:''}${o.status==='Review Pelanggan'?`<button class="btn small" data-action="revision" data-id="${esc(o.id)}">Minta Revisi</button><button class="btn small" data-action="complete" data-id="${esc(o.id)}">Terima Hasil</button>`:''}<button class="btn ghost small" data-action="contact">Hubungi Admin</button></div></article>`;}
function pageError(e){$('#page').innerHTML=`<div class="empty"><h2>Data belum dapat dimuat</h2><p>${esc(e.message)}</p><button class="btn" data-action="refresh">Coba lagi</button></div>`;}
function legacyHelp(){const faqs=[['Apakah perlu akun untuk melihat jasa?','Tidak. Katalog, detail layanan, dan harga bisa dilihat tanpa akun. Akun diperlukan saat checkout dan untuk mengakses pesanan.'],['Kapan pengerjaan dimulai?','Setelah admin memverifikasi pembayaran dan memastikan brief serta bahan sudah lengkap. Estimasi hari adalah waktu pengerjaan paket awal.'],['Apa yang termasuk dalam harga?','Lingkup paket dijelaskan pada masing-masing jasa. Kebutuhan di luar paket perlu dikonsultasikan sebelum pembayaran. Harga baru tidak berlaku surut pada pesanan yang sudah dibuat.'],['Bagaimana revisi dan pembatalan?','Jumlah revisi tercantum pada paket. Revisi berlaku dalam brief yang disepakati. Ajukan ketika hasil dibagikan pada tahap Proses Pengerjaan. Pembatalan dan pengembalian dana dikonsultasikan dengan admin berdasarkan progres pekerjaan.'],['Bagaimana layanan akademik digunakan?','Layanan berupa pendampingan pemahaman, review, perapian, serta pengolahan bahan yang sah. Pengguna bertanggung jawab atas isi, sumber, data, dan ketentuan institusinya. Tidak termasuk fabrikasi data atau penggantian pengerjaan ujian.'],['Apakah ada pembayaran atau OTP otomatis?','Versi ini menggunakan verifikasi pembayaran manual oleh admin. Nomor telepon belum diverifikasi OTP dan pemulihan password otomatis belum tersedia. Hubungi admin bila akun bermasalah.']];$('#page').innerHTML=`<div class="welcome"><div><h1>Dari kebutuhan, jadi beres.</h1><p>Kenali prosesnya sebelum memesan.</p></div></div><div class="steps"><div class="panel step"><b>01</b><h3>Pilih layanan</h3><p>Baca lingkup paket, estimasi, harga, dan revisi yang tersedia.</p></div><div class="panel step"><b>02</b><h3>Lengkapi & konfirmasi</h3><p>Masuk saat checkout, kirim brief, lalu ikuti instruksi pembayaran.</p></div><div class="panel step"><b>03</b><h3>Pantau & terima hasil</h3><p>Lihat progres di Pesanan Saya. Review hasil dan ajukan revisi bila perlu.</p></div></div><section class="panel" style="margin-bottom:24px"><h2 style="font-size:21px">Pertanyaan yang sering diajukan</h2>${faqs.map(f=>`<details><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('')}</section><section class="panel" id="privacy"><h2 style="font-size:20px">Privasi & penggunaan layanan</h2><p class="detailtext">Nama dan nomor telepon dipakai untuk akun serta komunikasi pesanan. Brief, tautan bahan, dan hasil hanya ditampilkan kepada pemilik pesanan serta admin. Data disimpan pada Spreadsheet yang dikelola pemilik JASAhub.id. Thumbnail jasa bersifat publik. Jangan mengirim password, identitas sensitif, atau bahan yang tidak kamu berhak bagikan.</p><p class="detailtext">Token sesi disimpan di browser agar tetap masuk setelah refresh; sesi server berlaku 8 jam. Tutup sesi lewat tombol Keluar pada perangkat bersama. Hubungi admin untuk permintaan koreksi atau penghapusan data. Pastikan tautan berkas menggunakan izin akses yang sesuai.</p></section><section class="infocta"><div><h3>Masih ada yang ingin ditanyakan?</h3><p>Admin siap membantu menjelaskan lingkup layananmu.</p></div><button class="btn" data-action="contact">Hubungi Admin ${icon('message',17)}</button></section>`;}
async function adminPage(version){if(!S.user){$('#page').innerHTML='<div class="empty"><h1 style="font-size:24px">Akses Admin</h1><p>Masuk dengan akun yang sudah diberi peran admin.</p><button class="btn primary" data-action="auth" data-mode="login">Masuk</button></div>';return;}if(S.user.role!=='admin'){$('#page').innerHTML='<div class="empty"><h1 style="font-size:24px">Akses terbatas</h1><p>Akun ini belum memiliki peran admin.</p><a class="btn" href="#catalog">Kembali ke katalog</a></div>';return;}$('#page').innerHTML=busy();try{const d=await api('adminData');if(version!==S.routeVersion)return;S.admin=d;renderAdmin();}catch(e){if(version===S.routeVersion)pageError(e);}}
function renderAdmin(){const d=S.admin;const paid=d.orders.filter(o=>o.paymentStatus==='Lunas'&&o.status!=='Dibatalkan').reduce((a,o)=>a+Number(o.price),0);$('#page').innerHTML=`<div class="sectionhead"><div><h1 style="font-size:25px">Dashboard Admin</h1><p>Kelola layanan dan pesanan dari satu tempat.</p></div><button class="btn small" data-action="refresh">${icon('refresh',16)} Muat ulang</button></div><div class="stats"><div class="stat"><span>Jasa aktif</span><strong>${d.products.filter(p=>p.active).length}</strong></div><div class="stat"><span>Pesanan belum selesai</span><strong>${d.orders.filter(o=>!['Selesai','Dibatalkan'].includes(o.status)).length}</strong></div><div class="stat"><span>Nilai pesanan lunas*</span><strong style="font-size:22px">${rupiah(paid)}</strong></div></div><p class="tiny muted">*Nilai pesanan lunas selain yang dibatalkan; bukan perhitungan laba atau arus kas.</p><div class="tabs">${[['products','Kelola Jasa'],['orders','Pesanan'],['categories','Kategori'],['settings','Pengaturan']].map(t=>`<button class="chip ${S.adminTab===t[0]?'active':''}" data-action="adminTab" data-tab="${t[0]}" aria-pressed="${S.adminTab===t[0]}">${t[1]}</button>`).join('')}</div><div id="adminPane"></div>`;renderAdminPane();}
function renderAdminPane(){const d=S.admin,el=$('#adminPane');if(S.adminTab==='products'){el.innerHTML=`<div class="sectionhead"><h2 style="font-size:18px">Semua layanan (${d.products.length})</h2><button class="btn primary small" data-action="editProduct">${icon('plus',16)} Tambah Jasa</button></div><div class="adminlist">${d.products.map(p=>`<article class="adminitem"><div><span class="badge ${p.active?'green':''}">${p.active?'Terbit':'Arsip / Draft'}</span><h3>${esc(p.title)}</h3><p>${esc(p.category)} · ${rupiah(p.price)} · ${p.days} hari</p></div><button class="btn small" data-action="editProduct" data-id="${esc(p.id)}">Edit Layanan</button></article>`).join('')||'<div class="empty">Belum ada layanan. Tambahkan jasa pertamamu.</div>'}</div>`;}else if(S.adminTab==='orders'){el.innerHTML=`<div class="adminlist">${d.orders.map(o=>{const u=d.customers.find(x=>x.id===o.userId);return `<article class="adminitem"><div><span class="tiny muted">${esc(o.id)}</span><h3>${esc(o.title)}</h3><p>${esc(u?.name||o.userId)} · ${esc(u?.phone||'')} · ${rupiah(o.price)}</p><div class="row wrap" style="margin-top:8px"><span class="badge">${esc(o.status)}</span></div></div><button class="btn small" data-action="editOrder" data-id="${esc(o.id)}">Kelola Pesanan</button></article>`;}).join('')||'<div class="empty"><h3>Belum ada pesanan masuk</h3><p>Pesanan pelanggan akan muncul di sini.</p></div>'}</div>`;}else if(S.adminTab==='categories'){el.innerHTML=`<section class="panel"><h2 style="font-size:18px;margin-bottom:18px">Kategori layanan</h2><div class="row wrap">${d.categories.map(c=>`<span class="badge">${esc(c.name)}</span>`).join('')}</div><form id="categoryForm" style="margin-top:24px" class="stack"><label class="field">Nama kategori baru<input name="name" minlength="2" maxlength="60" required></label><div class="error" id="categoryError" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">Tambah Kategori</button></form></section>`;}else{el.innerHTML=`<section class="panel"><h2 style="font-size:18px;margin-bottom:18px">Kontak & pembayaran</h2><form id="settingsForm" class="stack"><label class="field">Nomor WhatsApp admin<input name="whatsapp" type="tel" required value="${esc(d.settings.whatsapp||'')}" placeholder="6281234567890"></label><label class="field">Instruksi pembayaran<textarea name="paymentInfo" minlength="5" maxlength="2000" required>${esc(d.settings.paymentInfo||'')}</textarea><small>Isi bank/QRIS berupa tautan HTTPS, nama penerima, dan prosedur konfirmasi. Teks ini terlihat publik.</small></label><div class="error" id="settingsError" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">Simpan Pengaturan</button></form><p class="settingsnote" style="margin-top:22px">Pemberian peran admin dilakukan melalui fungsi promoteAdmin di Apps Script. Tidak ada tombol untuk menjadikan diri sendiri admin dari website.</p></section>`;}}
function editProduct(id){const p=S.admin.products.find(p=>p.id===id)||{title:'',category:S.admin.categories[0]?.name||'',description:'',price:25000,days:2,revisions:2,thumbnail:'',active:false,featured:false};showModal(id?'Edit layanan':'Tambah layanan baru',`<form id="productForm" data-id="${esc(id||'')}" class="formgrid"><label class="field full">Judul layanan<input name="title" value="${esc(p.title)}" minlength="3" maxlength="120" required></label><label class="field">Kategori<select name="category" required>${S.admin.categories.filter(c=>c.active===true||String(c.active)==='true').map(c=>`<option ${p.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Harga paket (Rp)<input name="price" type="number" min="1000" max="100000000" step="1" value="${p.price}" required></label><label class="field">Estimasi (hari)<input name="days" type="number" min="1" max="365" step="1" value="${p.days}" required></label><label class="field">Jumlah revisi<input name="revisions" type="number" min="0" max="20" step="1" value="${p.revisions}" required></label><label class="field full">Deskripsi & lingkup paket<textarea name="description" minlength="10" maxlength="5000" required>${esc(p.description)}</textarea></label><label class="field full">URL thumbnail (opsional)<input name="thumbnail" id="thumbnailUrl" value="${(p.thumbnail?.startsWith('data:')||p.thumbnail?.startsWith('drive:'))?'':esc(p.thumbnail)}" type="url" placeholder="https://…"><small>Gunakan URL gambar HTTPS atau unggah gambar di bawah. Kosong = ilustrasi bawaan.</small></label><label class="field full">Unggah thumbnail (opsional)<input type="file" id="thumbnailFile" accept="image/jpeg,image/png,image/webp"><small>JPG/PNG/WebP, maks. 5 MB. Disimpan di Drive admin.</small></label><div id="thumbnailPreview" class="full"></div><label class="check"><input type="checkbox" name="active" ${p.active?'checked':''}> Terbitkan layanan</label><label class="check"><input type="checkbox" name="featured" ${p.featured?'checked':''}> Pilihan JASAhub</label><div class="error full" id="productError" role="alert" tabindex="-1"></div><div class="formfoot full"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan Layanan</button></div></form>`);S.thumbnail=p.thumbnail||'';showThumbnailPreview();}
function showThumbnailPreview(){const el=$('#thumbnailPreview');if(!el)return;const src=safeUrl(S.thumbnail,true);el.innerHTML=src?`<img src="${esc(src)}" alt="Pratinjau thumbnail" style="width:160px;height:100px;object-fit:cover;border-radius:10px" referrerpolicy="no-referrer"><button type="button" class="btn ghost small" data-action="clearThumbnail">Hapus gambar</button>`:'';}
async function compressImage(file,preserveAlpha=false){if(file.size>5*1024*1024)throw Error('Ukuran gambar maksimal 5 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Gunakan JPG, PNG, atau WebP.');const image=await createImageBitmap(file);try{const canvas=document.createElement('canvas');let width=Math.min(600,image.width);for(let i=0;i<5;i++){canvas.width=width;canvas.height=Math.max(1,Math.round(image.height*width/image.width));if(canvas.height>1200){canvas.height=1200;canvas.width=Math.round(image.width*1200/image.height);}const ctx=canvas.getContext('2d');if(!preserveAlpha){ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [.75,.6,.45,.3]){const data=canvas.toDataURL(preserveAlpha?'image/webp':'image/jpeg',quality);if(data.length<=42000)return data;}width=Math.round(width*.75);}throw Error('Gambar masih terlalu besar. Coba gambar yang lebih sederhana.');}finally{image.close();}}
function editOrder(id){const o=S.admin.orders.find(x=>x.id===id);if(!o)return;const u=S.admin.customers.find(x=>x.id===o.userId);showModal('Kelola pesanan',`<div class="checkoutsummary"><h3>${esc(o.title)}</h3><span class="tiny">${esc(o.id)}<br>${esc(u?.name||'')} · ${esc(u?.phone||'')} · ${rupiah(o.price)}</span></div><p class="detailtext">${esc(o.brief)}</p>${safeUrl(o.materialUrl)?`<p><a href="${esc(safeUrl(o.materialUrl))}" target="_blank" rel="noopener noreferrer">Buka tautan bahan</a></p>`:''}<p class="tiny muted">Deadline ${esc(o.deadline)} · Sisa revisi ${Number(o.revisions)}</p><p class="detailtext">Referensi pembayaran: ${esc(o.paymentReference||'Belum dikirim')}</p><form id="orderForm" data-id="${esc(id)}" class="formgrid"><label class="field">Status pengerjaan<select name="status">${v2states.map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Status pembayaran<select name="paymentStatus">${payments.map(s=>`<option ${s===o.paymentStatus?'selected':''}>${s}</option>`).join('')}</select></label><label class="field full">Tautan hasil (HTTPS)<input name="resultUrl" type="url" maxlength="2000" value="${esc(o.resultUrl)}"></label><label class="field full">Catatan untuk pelanggan<textarea name="adminNote" maxlength="2000">${esc(o.adminNote)}</textarea></label><div class="error full" id="orderError" role="alert" tabindex="-1"></div><div class="formfoot full"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan Perubahan</button></div></form>`);}
function referenceModal(id,type){const revision=type==='revision';showModal(revision?'Ajukan revisi':'Konfirmasi pembayaran',`<p class="muted tiny">${revision?'Jelaskan perubahan sesuai brief awal. Satu pengajuan mengurangi satu jatah revisi.':'Masukkan nama pengirim, waktu transfer, bank, dan/atau tautan bukti. Admin akan memeriksa pembayaran secara manual.'}</p><form id="referenceForm" data-id="${esc(id)}" data-type="${type}" class="stack"><label class="field">${revision?'Catatan revisi':'Referensi pembayaran'}<textarea name="value" minlength="5" maxlength="${revision?1500:300}" required></textarea></label><div id="referenceError" class="error" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">Kirim ${revision?'Revisi':'Konfirmasi'}</button></form>`);}
async function route(){const version=++S.routeVersion;let hash=location.hash.slice(1)||'catalog';if(hash==='main')hash='catalog';const page=hash.split('/')[0];const name={catalog:'Eksplor Jasa',orders:'Pesanan Saya',admin:'Dashboard Admin',help:'Cara Pesan & FAQ'}[page]||'Eksplor Jasa';document.title=name+' — JASAhub.id';$('#breadcrumb').textContent=name;document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===page);if(a.dataset.route===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});closeNav();setNotice();if(page==='orders')await ordersPage(version);else if(page==='admin')await adminPage(version);else if(page==='help')help();else catalog();hydrate();}
function setNavOpen(open){
 const sidebar=$('#sidebar'),button=$('#menuToggle');
 sidebar.classList.toggle('open',open);sidebar.inert=!open;sidebar.setAttribute('aria-hidden',String(!open));
 $('#navBackdrop').classList.toggle('open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Tutup navigasi':'Buka navigasi');
 if(!open&&sidebar.contains(document.activeElement))button.focus({preventScroll:true});
}
function closeNav(){setNavOpen(false);}
async function refreshCatalog(){const d=await api('catalog');S.products=d.products;S.categories=d.categories;S.settings=d.settings;S.loadError=false;}
async function boot(){topbar();hydrate();$('#page').innerHTML=catalogSkeleton();if(!CONFIG.API_URL){S.products=DEMOS;S.categories=CATEGORIES.map((name,i)=>({id:'C-'+i,name}));}else{try{await refreshCatalog();}catch(e){S.loadError=true;S.connectionError=e.message;toast(e.message);}if(S.token)await restoreAccount();}topbar();await route();}
$('#menuToggle').addEventListener('click',()=>setNavOpen(!$('#sidebar').classList.contains('open')));$('#navBackdrop').addEventListener('click',closeNav);
$('#modal').addEventListener('close',()=>{S.pending=false;S.returnFocus?.isConnected&&S.returnFocus.focus({preventScroll:true});});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();});
window.addEventListener('hashchange',()=>{route();$('#main').focus({preventScroll:true});});
document.addEventListener('input',e=>{if(e.target.id==='search'){S.search=e.target.value;renderProducts();}if(e.target.id==='thumbnailUrl'){S.thumbnail=e.target.value.trim();showThumbnailPreview();}});
document.addEventListener('change',async e=>{if(e.target.id==='sort'){S.sort=e.target.value;renderProducts();}if(e.target.id==='thumbnailFile'&&e.target.files[0]){const input=e.target;const button=$('button[type=submit]',$('#productForm'));button.disabled=true;try{S.thumbnail=await uploadImage(input.files[0],'thumbnail');$('#thumbnailUrl').value='';showThumbnailPreview();$('#productError').textContent='';}catch(error){$('#productError').textContent=error.message;input.value='';}finally{button.disabled=false;}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='detail')detail(b.dataset.id);
 else if(a==='checkout')checkout();
 else if(a==='close')closeModal();
 else if(a==='contact')contact();
 else if(a==='auth')auth(b.dataset.mode||'login');
 else if(a==='authTab')auth(b.dataset.mode,S.pending);
 else if(a==='togglePassword'){const input=$('input',b.parentElement);const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Sembunyi':'Lihat';b.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');}
 else if(a==='filter'){S.category=b.dataset.name;renderFilters();renderProducts();}
 else if(a==='resetFilters'){S.search='';S.category='Semua Jasa';$('#search').value='';renderFilters();renderProducts();}
 else if(a==='explore'){$('#catalogSection').scrollIntoView({behavior:'smooth'});$('#search').focus({preventScroll:true});}
 else if(a==='refresh')await route();
 else if(a==='reload'){b.disabled=true;clearBrowserCatalog();$('#page').innerHTML=catalogSkeleton();try{await refreshCatalog();}catch(error){S.loadError=true;S.connectionError=error.message;}await route();}
 else if(a==='privacy'){location.hash='help';setTimeout(()=>$('#privacy')?.scrollIntoView(),100);}
 else if(a==='logout'){b.disabled=true;try{await api('logout');}finally{S.token='';S.user=null;S.admin=null;S.orders=null;S.sessionIssue='';persistSessionToken('');topbar();await route();toast('Kamu sudah keluar.');}}
 else if(a==='adminTab'){S.adminTab=b.dataset.tab;renderAdmin();}
 else if(a==='editProduct')editProduct(b.dataset.id);
 else if(a==='editOrder')editOrder(b.dataset.id);
 else if(a==='clearThumbnail'){S.thumbnail='';$('#thumbnailUrl').value='';$('#thumbnailFile').value='';showThumbnailPreview();}
 else if(a==='pay')referenceModal(b.dataset.id,'pay');
 else if(a==='revision')referenceModal(b.dataset.id,'revision');
 else if(a==='complete'){showModal('Terima hasil pengerjaan',`<p class="muted">Pastikan kamu sudah memeriksa hasil. Pesanan akan ditandai selesai.</p><form id="completeForm" data-id="${esc(b.dataset.id)}"><div id="completeError" class="error" role="alert" tabindex="-1"></div><div class="formfoot"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Ya, Terima Hasil</button></div></form>`,true);}
 }catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));
 if(f.id==='authForm')return authSubmit(f);
 if(f.id==='checkoutForm')return formTask(f,'#checkoutError',async()=>{const order=await api('createOrder',{...d,productId:S.selected.id,packageId:S.package.id,expectedPrice:S.package.price,requestId:f.dataset.request});$('#modal').close();location.hash='orders';await route();checkoutSuccess(order);});
 if(f.id==='productForm')return formTask(f,'#productError',async()=>{const packages=Array.from(f.querySelectorAll('.pkg-editor')).map(section=>{const i=section.dataset.packageIndex;return {name:section.dataset.packageName,price:Number(d['pkgPrice'+i]),days:Number(d['pkgDays'+i]),revisions:Number(d['pkgRevisions'+i]),features:d['pkgFeatures'+i]};});if(!packages.length)throw Error('Sisakan minimal satu paket layanan.');const saved=await api('saveProduct',{...d,id:f.dataset.id||undefined,price:packages[0].price,days:packages[0].days,revisions:packages[0].revisions,packages,thumbnail:S.thumbnail,active:f.elements.active.checked,featured:f.elements.featured.checked});await syncAdmin();renderAdmin();editProduct(saved.id);toast('Layanan berhasil disimpan. Tambahkan preview bila diperlukan.');});
 if(f.id==='orderForm')return formTask(f,'#orderError',async()=>{await api('updateOrder',{...d,id:f.dataset.id,paymentVerified:f.elements.paymentVerified?.checked===true});$('#modal').close();await route();toast('Pesanan berhasil diperbarui.');});
 if(f.id==='categoryForm')return formTask(f,'#categoryError',async()=>{await api(f.dataset.id?'updateCategory':'saveCategory',{...d,id:f.dataset.id,active:f.elements.active.checked});await syncAdmin();$('#modal').close();renderAdmin();toast('Kategori berhasil disimpan.');});
 if(f.id==='settingsForm')return formTask(f,'#settingsError',async()=>{await api('saveSettings',{...d,logoUrl:S.customLogo||'',qrisImage:S.qrisImage||''});await syncAdmin();topbar();renderAdmin();toast('Pengaturan berhasil disimpan.');});
 if(f.id==='referenceForm')return formTask(f,'#referenceError',async()=>{await api(f.dataset.type==='revision'?'requestRevision':'confirmPayment',{id:f.dataset.id,reference:d.value,note:d.value});$('#modal').close();await route();toast('Berhasil dikirim ke admin.');});
 if(f.id==='completeForm')return formTask(f,'#completeError',async()=>{await api('completeOrder',{id:f.dataset.id});$('#modal').close();await route();toast('Pesanan selesai. Terima kasih!');});
});
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){const img=e.target;const holder=img.parentElement;if(holder.classList.contains('thumb'))holder.innerHTML='<div class="art" style="--art-bg:#eaf0ff;--art-ink:#244f9e">'+icon('doc',48)+'<span class="tiny">Pratinjau tidak tersedia</span></div>'; }},true);
/* ===== Dark Marketplace — enhancements ===== */
const ORIGINAL_LOGO='/assets/logo.png';
Object.assign(S,{package:null,galleryIndex:0,priceRange:'all',adminSearch:'',adminStatus:'all',customerSearch:'',adminTab:'overview'});
const v2states=['Belum Dibayar','Proses Pengerjaan','Selesai'];
DEMOS.forEach((p,i)=>{p.shortDescription=p.description.slice(0,180);p.badge=i<3?'Populer':i>5?'Terbaru':'';p.createdAt=new Date(Date.now()-i*86400000).toISOString();p.packages=['Basic','Standard','Premium'].map((name,j)=>({id:p.id+'-PKG-'+j,name,price:Math.round(p.price*[1,1.8,3][j]/1000)*1000,days:p.days+j,revisions:p.revisions+j,features:j===0?'Lingkup paket awal sesuai deskripsi\nFile hasil digital':j===1?'Lingkup diperluas setelah konfirmasi\nFile editable bila tersedia\nTambahan satu revisi':'Lingkup lengkap setelah konfirmasi\nFile editable bila tersedia\nTambahan dua revisi'}));p.previews=i<2?[{id:p.id+'-PRE-1',demo:true,caption:'Contoh susunan halaman'},{id:p.id+'-PRE-2',demo:true,caption:'Contoh tampilan isi'}]:[];});
function brandImg(){return `<img class="brand-image" src="${esc(safeUrl(S.settings.logoUrl,true)||ORIGINAL_LOGO)}" alt="${esc(S.settings.siteName||'JASAhub.id')}" width="155" height="54">`;}
function updateBrand(){document.querySelectorAll('.brand').forEach(el=>el.innerHTML=brandImg());$('#footerCopy').textContent='© '+new Date().getFullYear()+' '+(S.settings.siteName||'JASAhub.id')+'. Semua hak dilindungi.';$('#footerDescription').textContent=S.settings.footerText||'Partner digital untuk ide, karya, dan kebutuhanmu.';if($('#footerContact'))$('#footerContact').textContent=S.settings.contactInfo||'Konsultasikan kebutuhan layananmu melalui WhatsApp.';const meta=$('meta[name=description]');if(meta)meta.content=S.settings.siteDescription||'JASAhub.id — Partner jasa digital untuk kebutuhanmu.';const footerLogo=$('#footerLogo');if(footerLogo)footerLogo.innerHTML=brandImg();}
function topbar(){const el=$('#topactions');el.innerHTML=S.user?`<a href="#profile" class="row" style="color:inherit;text-decoration:none"><span class="avatar" aria-hidden="true">${esc(S.user.name.slice(0,1).toUpperCase())}</span><span class="tiny userlabel">${esc(S.user.name)}</span></a><button class="iconbtn" data-action="logout" aria-label="Keluar akun">${icon('logout')}</button>`:`<button class="btn ghost small" data-action="auth" data-mode="register">Daftar</button><button class="btn primary small" data-action="auth" data-mode="login">Masuk ${icon('arrow',14)}</button>`;$('#adminLink').hidden=S.user?.role!=='admin';$('#accountLink').hidden=!S.user;if($('#adminSubnav'))$('#adminSubnav').hidden=S.user?.role!=='admin';updateBrand();}
function art(product){const index=Math.max(0,CATEGORIES.indexOf(product.category));const themes=[['doc','Laporan','Dokumen lebih rapi'],['slide','Presentasi','Saatnya tampil beda'],['chart','Data & Excel','Dari data jadi insight'],['pen','Desain','Wujudkan ide kreatif'],['cad','Teknik','Setiap detail berarti'],['book','Belajar','Pahami, lalu kuasai']];const t=themes[index];return `<div class="art" data-theme="${index}" aria-hidden="true"><div class="arttype"><small>${t[2]}</small>${t[1]}</div><div class="artpaper">${icon(t[0],45)}</div></div>`;}
function thumb(p){const src=safeUrl(p.thumbnail,true);return `<div class="thumb">${src?`<img src="${esc(src)}" alt="Thumbnail ${esc(p.title)}" loading="lazy" width="600" height="360" referrerpolicy="no-referrer">`:art(p)}${p.badge||p.featured?`<span class="badge">${esc(p.badge||(p.featured?'Unggulan':''))}</span>`:''}</div>`;}
function card(p){return `<article class="service">${thumb(p)}<div class="servicebody"><div class="cat">${esc(p.category)}</div><h3><a href="#service/${encodeURIComponent(p.id)}" style="color:inherit;text-decoration:none">${esc(p.title)}</a></h3><p class="desc">${esc(p.shortDescription||p.description)}</p><div class="meta"><span>${icon('clock',13)} ${p.days} hari</span><span>${icon('refresh',13)} ${p.revisions} revisi</span></div><div class="cardfoot"><div class="price"><small>Mulai dari</small><strong>${rupiah(p.price)}</strong></div><button class="btn" data-action="detail" data-id="${esc(p.id)}" aria-label="Lihat detail ${esc(p.title)}"><span class="buttonlabel">Lihat Detail</span>${icon('arrow',17)}</button></div></div></article>`;}
function heroScene(){return `<div class="scene" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><span class="orbit-spark"></span><div class="floating-tile two">${icon('book',42)}</div><div class="floating-tile three">${icon('doc',27)}</div><div class="laptop"><div class="screen"><div class="screenbar"><i></i><i></i><i></i><i></i></div><div class="screenmain"><div class="screenhead">Your digital partner.</div><div class="screenblocks"><i></i><i></i><i></i></div><div style="height:5px;background:#c4a4e4;margin-top:13px;width:80%;border-radius:3px"></div><div style="height:5px;background:#d0b7e8;margin-top:7px;width:55%;border-radius:3px"></div></div></div><div class="keyboard"></div></div><div class="floating-tile">${icon('slide',36)}</div><div class="floating-tile four">${icon('chart',26)}</div></div>`;}
function catalog(){const title=S.settings.heroTitle||'Semua Kebutuhan Digital, Satu Tempat.';const mid=Math.ceil(title.length*.6);const split=title.includes(',')?title.indexOf(',')+1:(title.lastIndexOf(' ',mid)>0?title.lastIndexOf(' ',mid):title.length);const featured=S.products.filter(p=>p.featured).slice(0,4);$('#page').innerHTML=`
<section class="hero" aria-labelledby="heroTitle"><div class="herotext"><span class="badge">YOUR DIGITAL SERVICE PARTNER</span><h1 id="heroTitle" style="font-size:inherit"><span style="font-family:var(--heading);font-size:clamp(36px,4.1vw,56px);font-weight:800;line-height:1.15;display:block;letter-spacing:-.055em;margin:18px 0 20px">${esc(title.slice(0,split))}<br><span style="color:#ba6cff">${esc(title.slice(split).trim())}</span></span></h1><p>${esc(S.settings.heroDescription||'Temukan layanan digital yang membantu pekerjaanmu menjadi lebih mudah, rapi, dan efisien — dengan hasil berkualitas.')}</p><div class="row wrap"><button class="btn primary" data-action="explore">Jelajahi Jasa ${icon('arrow',16)}</button><a href="#help" class="btn">Cara Order</a></div><div class="herofoot"><span>${icon('check',13)} Harga transparan</span><span>${icon('check',13)} Paket fleksibel</span><span>${icon('check',13)} Progres terpantau</span></div></div><div class="heroart">${heroScene()}</div></section>
<div class="metrics"><div class="metric"><strong>${S.products.length}</strong><span>Layanan tersedia</span></div><div class="metric"><strong>${S.categories.length}</strong><span>Kategori pilihan</span></div><div class="metric"><strong>3</strong><span>Pilihan paket</span></div><div class="metric"><strong>1 Hub</strong><span>Banyak solusi digital</span></div></div>
<section><div class="sectionhead"><h2>Kategori Layanan</h2><a class="sectionlink" href="#catalog/all">Lihat Semua ${icon('arrow',14)}</a></div><div class="categorytiles">${S.categories.map((c,i)=>`<button class="categorytile" data-action="categoryJump" data-name="${esc(c.name)}"><span>${icon(c.icon||['doc','slide','chart','pen','cad','book'][i%6],29)}</span><strong>${esc(c.name)}</strong></button>`).join('')}</div></section>
${featured.length?`<section class="catalog-block"><div class="sectionhead"><div><h2>Layanan Unggulan</h2><p>Pilihan layanan untuk membuat harimu lebih ringan.</p></div><a class="sectionlink" href="#catalog/all">Lihat Semua ${icon('arrow',14)}</a></div><div class="grid">${featured.map(card).join('')}</div></section>`:''}
<section class="catalog-block" id="catalogSection" aria-labelledby="catalogTitle"><div class="sectionhead"><div><h2 id="catalogTitle">Semua Layanan</h2><p>Temukan bantuan yang pas dengan kebutuhanmu.</p></div><span class="count" id="serviceCount"></span></div><div class="tools"><label class="searchbox">${icon('search',19)}<input id="search" type="search" placeholder="Cari layanan, misalnya desain presentasi…" aria-label="Cari jasa" value="${esc(S.search)}"></label><select id="priceRange" aria-label="Filter harga"><option value="all">Semua harga</option><option value="under50">Di bawah Rp50.000</option><option value="50to100">Rp50.000–100.000</option><option value="over100">Di atas Rp100.000</option></select><select id="sort" aria-label="Urutkan jasa"><option value="featured">Unggulan</option><option value="popular">Populer</option><option value="newest">Terbaru</option><option value="low">Harga termurah</option><option value="high">Harga termahal</option><option value="fast">Pengerjaan tercepat</option></select></div><div class="filters" id="categoryFilters"></div><div class="grid" id="serviceGrid"></div><p class="previewnote">Harga mulai berlaku untuk paket pertama yang tersedia. Pilih paket pada detail layanan. ${!CONFIG.API_URL?'Data ini adalah contoh yang dapat diganti admin.':''}</p></section>
<section><div class="sectionhead"><h2>Kenapa Pilih JASAhub?</h2></div><div class="valuebar">${[['layers','Banyak Pilihan','Beragam layanan untuk kebutuhan digitalmu.'],['message','Proses Mudah','Pilih paket, bayar QRIS, lalu kirim bukti via WhatsApp.'],['shield','Lingkup Jelas','Harga, estimasi, dan revisi tercantum sebelum pesan.'],['check','Progres Terpantau','Status pengerjaan bisa dilihat dari akunmu.']].map(v=>`<div class="value"><span class="valueicon">${icon(v[0],22)}</span><div><strong>${v[1]}</strong><p>${v[2]}</p></div></div>`).join('')}</div></section>
<section class="infocta"><div><h3>Ide sudah ada. Tinggal cari bantuan yang tepat.</h3><p>Ceritakan kebutuhanmu, diskusikan lingkupnya, lalu mulai bersama JASAhub.</p></div><button class="btn" data-action="contact">Konsultasi via WhatsApp ${icon('arrow',16)}</button></section>
<section class="faqgrid"><div><span class="eyebrow" style="color:#bd7bf1">SEBELUM MULAI</span><h2>Ada yang ingin<br>kamu tanyakan?</h2><p>Kenali alurnya agar pesananmu lebih nyaman.</p><a href="#help" class="sectionlink">Baca semua panduan ${icon('arrow',15)}</a></div><div><details><summary>Haruskah login untuk melihat layanan?</summary><p>Tidak. Kamu bebas menjelajahi katalog dan paket. Akun baru diperlukan ketika checkout.</p></details><details><summary>Bagaimana cara memesan jasa?</summary><p>Pilih jasa dan paket, login saat checkout, simpan pesanan, bayar QRIS, lalu lampirkan bukti di WhatsApp admin. Pesanan tetap Belum Dibayar sampai admin memverifikasi.</p></details><details><summary>Apakah hasil bisa direvisi?</summary><p>Bisa sesuai jumlah revisi pada paket dan brief yang telah disepakati. Ajukan dari Pesanan Saya saat admin membagikan hasil pada tahap Proses Pengerjaan.</p></details></div></section>`;
$('#sort').value=S.sort;$('#priceRange').value=S.priceRange;renderFilters();renderProducts();}
function renderProducts(){let list=S.products.filter(p=>(S.category==='Semua Jasa'||p.category===S.category)&&[p.title,p.category,p.description].join(' ').toLowerCase().includes(S.search.toLowerCase())&&(S.priceRange==='all'||S.priceRange==='under50'&&p.price<50000||S.priceRange==='50to100'&&p.price>=50000&&p.price<=100000||S.priceRange==='over100'&&p.price>100000));list.sort((a,b)=>S.sort==='low'?a.price-b.price:S.sort==='high'?b.price-a.price:S.sort==='fast'?a.days-b.days:S.sort==='newest'?Date.parse(b.createdAt)-Date.parse(a.createdAt):S.sort==='popular'?(Number(b.orderCount)||0)-(Number(a.orderCount)||0):Number(b.featured)-Number(a.featured));if(!$('#serviceCount'))return;$('#serviceCount').textContent=list.length+' layanan';$('#serviceGrid').innerHTML=list.map(card).join('')||`<div class="empty">${icon('search',32)}<h3>${S.loadError?'Katalog belum terhubung':'Belum ada jasa yang cocok'}</h3><p>Coba kata kunci, kategori, atau rentang harga lain.</p><button class="btn" data-action="resetAll">Reset filter</button></div>`;}
function detail(id){const next='service/'+encodeURIComponent(id);if(location.hash.slice(1)===next)route();else location.hash=next;if($('#modal').open)$('#modal').close();}
function renderService(id){const p=S.products.find(x=>x.id===id);if(!p){$('#page').innerHTML='<div class="empty"><h1 style="font-size:25px">Layanan tidak tersedia</h1><p>Layanan mungkin sudah diarsipkan atau kategorinya dinonaktifkan.</p><a href="#catalog" class="btn">Kembali ke katalog</a></div>';return;}S.selected=p;if(!S.package||!p.packages?.some(x=>x.id===S.package.id))S.package=p.packages?.[0]||{id:'',name:'Basic',price:p.price,days:p.days,revisions:p.revisions,features:p.description};S.galleryIndex=0;
$('#page').innerHTML=`<section class="detailpage"><div class="detailcrumb"><a href="#catalog">Beranda</a><span>/</span><a href="#catalog/all">${esc(p.category)}</a><span>/</span><span>${esc(p.title)}</span></div><div class="detail-layout"><div><div class="detailhero">${thumb(p)}</div><h1>${esc(p.title)}</h1><span class="badge">${esc(p.category)}</span><p class="description" style="margin-top:18px">${esc(p.description)}</p><div class="detailstats"><div>Estimasi mulai<strong>${p.days} hari</strong></div><div>Revisi mulai<strong>${p.revisions} kali</strong></div><div>Format hasil<strong>File digital</strong></div></div></div><aside class="detail-side">${p.previews?.length?`<div class="detailbox gallery"><h2>Preview Hasil Pekerjaan</h2><p class="tiny muted">${p.previews.some(x=>x.demo)?'Contoh ilustrasi, bukan portofolio klien.':'Contoh hasil yang disediakan admin.'}</p><div id="previewGallery"></div></div>`:''}<div class="detailbox"><h2>Tentang Layanan</h2><ul class="checklist">${['Lingkup dan harga paket tercantum jelas','Brief disesuaikan dengan kebutuhanmu','File hasil dikirim melalui tautan','Revisi sesuai paket yang dipilih','Konsultasi kebutuhan lewat WhatsApp'].map(t=>`<li>${icon('check',15)}<span>${t}</span></li>`).join('')}</ul><div class="splitline"></div><p class="tiny muted">Estimasi dimulai setelah brief lengkap dan pembayaran dikonfirmasi. Diskusikan kebutuhan di luar lingkup paket sebelum membayar.</p><button class="btn" style="width:100%" data-action="contact">${icon('message',16)} Tanya Admin</button></div></aside></div><h2 class="package-heading" id="packageHeading">Pilih Paket Layanan</h2><div class="packages" id="packageCards" role="radiogroup" aria-labelledby="packageHeading"></div><p class="tiny muted">Pilih paket yang tersedia sesuai kebutuhan dan lingkup pekerjaan. Pastikan deskripsinya sesuai kebutuhanmu.</p><section class="detailsrecs"><div class="sectionhead"><h2>Layanan Lain untukmu</h2><a class="sectionlink" href="#catalog/all">Semua Layanan ${icon('arrow',15)}</a></div><div class="grid">${S.products.filter(x=>x.id!==id).slice(0,4).map(card).join('')}</div></section></section>`;renderPackageCards();updateMobileChrome();if(p.previews?.length)renderGallery();}
function renderPackageCards(){const p=S.selected;$('#packageCards').innerHTML=(p.packages?.length?p.packages:[S.package]).map((x,i)=>`<div class="package ${S.package.id===x.id?'selected':''} ${i===1?'recommended':''}">${i===1?'<span class="badge">Rekomendasi</span>':''}<label class="row"><input type="radio" name="chosenPackage" value="${esc(x.id)}" ${S.package.id===x.id?'checked':''}><strong>${esc(x.name)}</strong></label><ul class="checklist">${String(x.features||'').split('\n').filter(Boolean).map(f=>`<li>${icon('check',13)}<span>${esc(f)}</span></li>`).join('')}<li>${icon('clock',13)} ${x.days} hari pengerjaan</li><li>${icon('refresh',13)} ${x.revisions} revisi</li></ul><div class="pkgprice">${rupiah(x.price)}</div><button class="btn primary" data-action="packageCheckout" data-id="${esc(x.id)}">Pilih Paket ${icon('arrow',14)}</button></div>`).join('');}
function demoPreview(preview,small=false){return `<div class="preview-sheet ${small?'small':''}"><span class="eyebrow">CONTOH PREVIEW</span><h3>${esc(preview.caption)}</h3><div class="sheetline"></div><div class="sheetline" style="width:65%"></div><div class="sheetcols"><i></i><i></i></div><div class="sheetline"></div><div class="sheetline"></div><div class="sheetline" style="width:75%"></div></div>`;}
function renderGallery(){const list=S.selected.previews;S.galleryIndex=(S.galleryIndex+list.length)%list.length;const x=list[S.galleryIndex];$('#previewGallery').innerHTML=`<div class="gallery-display" id="galleryDisplay">${x.demo?demoPreview(x):`<img id="previewImage" src="${esc(safeUrl(x.image,true))}" alt="${esc(x.caption||'Preview halaman '+(S.galleryIndex+1))}" referrerpolicy="no-referrer" width="700" height="900">`}</div><div class="gallery-controls"><button class="iconbtn" data-action="galleryPrev" aria-label="Preview sebelumnya">${icon('arrow',17).replace('<svg ','<svg style="transform:rotate(180deg)" ')}</button><span aria-live="polite">${S.galleryIndex+1} / ${list.length}</span><button class="iconbtn" data-action="galleryZoom" aria-label="Perbesar preview">${icon('search',17)}</button><button class="iconbtn" data-action="galleryFull" aria-label="Preview layar penuh">${icon('grid',17)}</button><button class="iconbtn" data-action="galleryNext" aria-label="Preview berikutnya">${icon('arrow',17)}</button></div><div class="gallery-thumbs">${list.map((im,i)=>`<button data-action="galleryAt" data-index="${i}" class="${i===S.galleryIndex?'active':''}" aria-label="Buka preview ${i+1}" aria-pressed="${i===S.galleryIndex}">${im.demo?demoPreview(im,true):`<img src="${esc(safeUrl(im.image,true))}" alt="" loading="lazy" referrerpolicy="no-referrer">`}</button>`).join('')}</div><p class="graphic-caption">${esc(x.caption||'Preview halaman '+(S.galleryIndex+1))}</p>`;let start;const display=$('#galleryDisplay');display.addEventListener('touchstart',e=>{start=e.changedTouches[0].clientX;},{passive:true});display.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-start;if(Math.abs(delta)>45){S.galleryIndex+=delta<0?1:-1;renderGallery();}},{passive:true});}
function checkout(){if(!S.selected)return;if(!CONFIG.API_URL){toast('Pratinjau desain: hubungkan API_URL untuk mengaktifkan checkout.');return;}if(!S.user){auth('login',true);return;}const p=S.selected,x=S.package||p.packages[0];const min=localDate(new Date(Date.now()+x.days*86400000));showModal('Checkout Pesanan',`<div class="row tiny muted" style="margin-bottom:20px"><span class="badge">1 · Detail Pesanan</span><span>2 · Konfirmasi</span><span>3 · WhatsApp</span></div><div class="checkoutsummary"><span class="eyebrow muted">LAYANAN PILIHAN</span><h3>${esc(p.title)}</h3><div class="row spread"><span class="tiny muted">Paket ${esc(x.name)} · ${x.days} hari · ${x.revisions} revisi</span><strong>${rupiah(x.price)}</strong></div></div><form id="checkoutForm" class="stack" data-request="${randomHex()}"><div class="row spread wrap tiny"><span>Pemesan: <strong>${esc(S.user.name)}</strong></span><span>WhatsApp: ${esc(S.user.phone)}</span></div><label class="field">Tanggal deadline<input type="date" name="deadline" min="${min}" required><small>Paling cepat ${esc(min)}. Jadwal final dikonfirmasi bersama admin.</small></label><label class="field">Detail kebutuhan<textarea name="brief" minlength="15" maxlength="5000" required placeholder="Tujuan, jumlah halaman/slide, format hasil, dan arahan khusus…"></textarea></label><label class="field">Tautan bahan (opsional)<input type="url" name="materialUrl" placeholder="https://drive.google.com/…" maxlength="2000"><small>Atur izin akses sesuai kebutuhan. Jangan kirim data sensitif.</small></label><label class="field">Catatan tambahan (opsional)<textarea name="customerNote" maxlength="2000" style="min-height:75px" placeholder="Catatan lain untuk admin…"></textarea></label><label class="check"><input type="checkbox" required> Saya menyetujui lingkup paket dan ketentuan layanan.</label><div id="checkoutError" class="error" role="alert" tabindex="-1"></div><div class="row spread"><span class="muted">Total</span><strong style="font-size:23px;color:#d7a6ff">${rupiah(x.price)}</strong></div><button type="submit" class="btn primary">${icon('message',18)} Buat Pesanan & Lanjut WhatsApp</button><p class="formhint">Pesanan disimpan terlebih dahulu dengan status Menunggu Konfirmasi. WhatsApp membuka draft pesan; kamu tetap perlu menekan Kirim.</p></form>`);}
function orderMessage(order){return `Halo Admin JASAhub.id, saya ingin mengonfirmasi pesanan.\n\nID: ${order.id}\nNama: ${S.user.name}\nWhatsApp: ${S.user.phone}\nJasa: ${order.title}\nPaket: ${order.packageName||'Basic'}\nHarga: ${rupiah(order.price)}\nDeadline: ${order.deadline}\n\nDetail kebutuhan:\n${order.brief}\n\nBahan: ${order.materialUrl||'-'}\nCatatan: ${order.customerNote||'-'}`;}
function whatsappLink(message,phone=S.settings.whatsapp){return /^628\d{7,11}$/.test(phone||'')?'https://wa.me/'+phone+'?text='+encodeURIComponent(message):'';}
function checkoutSuccess(order){const message=orderMessage(order);const link=whatsappLink(message);showModal('Pesanan berhasil disimpan',`<span class="badge green">${icon('check',14)} ${esc(order.status)}</span><h3 style="font-size:21px;margin:16px 0 10px">${esc(order.id)}</h3><p class="muted tiny">Lanjutkan konfirmasi ke WhatsApp admin. Jika jendela baru tidak terbuka, gunakan tombol di bawah.</p><textarea id="waMessage" class="copyarea" readonly aria-label="Pesan konfirmasi pesanan">${esc(message)}</textarea><div class="formfoot"><button class="btn" data-action="copyOrderMessage">Salin Pesan</button>${link?`<a class="btn primary" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Lanjut ke WhatsApp ${icon('arrow',16)}</a>`:'<span class="error">Nomor admin belum diatur. Pesanan sudah tersimpan; buka Pesanan Saya untuk memantau status.</span>'}<button class="btn" data-action="viewOrders">Lihat Pesanan</button></div>`);if(link)window.open(link,'_blank','noopener,noreferrer');}
const baseOrderCard=legacyOrderCard;
function orderCard(o){let html=baseOrderCard(o);html=html.replace(`<h3>${esc(o.title)}</h3>`,`<h3>${esc(o.title)}</h3><p class="tiny muted">Paket ${esc(o.packageName||'Basic')}${o.customerNote?' · Catatan: '+esc(o.customerNote):''}</p>`);const link=whatsappLink('Halo Admin, saya ingin menanyakan pesanan '+o.id+'.');if(link)html=html.replace('<button class="btn ghost small" data-action="contact">Hubungi Admin</button>',`<a class="btn ghost small" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Hubungi Admin</a>`);return html;}
function profilePage(){if(!S.user){$('#page').innerHTML='<div class="empty"><h1 style="font-size:24px">Akun Saya</h1><p>Masuk untuk mengelola profilmu.</p><button class="btn primary" data-action="auth" data-mode="login">Masuk</button></div>';return;}$('#page').innerHTML=`<div class="accounthead"><span class="avatar">${esc(S.user.name.slice(0,1).toUpperCase())}</span><div><h1 style="font-size:27px">${esc(S.user.name)}</h1><p class="tiny muted" style="margin:5px 0">${esc(S.user.phone)} · ${S.user.role==='admin'?'Administrator':'Pelanggan'}</p></div></div><div class="profile-grid"><section class="panel"><h2 style="font-size:19px;margin-bottom:20px">Edit Profil</h2><form id="profileForm" class="stack"><label class="field">Nama lengkap<input name="name" minlength="2" maxlength="80" required value="${esc(S.user.name)}" autocomplete="name"></label><label class="field">Nomor WhatsApp<input name="phone" type="tel" required value="${esc(S.user.phone)}" autocomplete="tel"><small>Nomor harus unik. Versi ini belum memverifikasi kepemilikan nomor melalui OTP.</small></label><div class="error" id="profileError" role="alert" tabindex="-1"></div><button type="submit" class="btn primary">Simpan Profil</button></form></section><section class="panel"><h2 style="font-size:19px;margin-bottom:20px">Ubah Password</h2><form id="passwordForm" class="stack"><label class="field">Password saat ini<span class="pw"><input name="oldPassword" type="password" required autocomplete="current-password"><button type="button" data-action="togglePassword" aria-label="Tampilkan password">Lihat</button></span></label><label class="field">Password baru<span class="pw"><input name="newPassword" type="password" minlength="6" maxlength="128" required autocomplete="new-password"><button type="button" data-action="togglePassword" aria-label="Tampilkan password">Lihat</button></span><small>Minimal 6 karakter. Perubahan akan mengakhiri sesi di perangkat lain.</small></label><div class="error" id="passwordError" role="alert" tabindex="-1"></div><button type="submit" class="btn primary">Perbarui Password</button></form></section></div><section class="infocta"><div><h3>Lihat pekerjaan yang sedang berjalan.</h3><p>Pantau progres, hasil, dan revisi dari riwayat pesananmu.</p></div><a class="btn" href="#orders">Pesanan Saya ${icon('arrow',16)}</a></section>`;}
function busy(){return '<div role="status"><p class="tiny muted">Memuat data terbaru…</p><div class="skeleton-grid" aria-hidden="true"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></div>';}
function renderAdmin(){const d=S.admin;const metrics=[['Total Jasa',d.products.length],['Pelanggan',d.customers.filter(x=>x.role!=='admin').length],['Total Pesanan',d.orders.length],['Belum Dibayar',d.orders.filter(o=>o.status==='Belum Dibayar').length],['Proses Pengerjaan',d.orders.filter(o=>o.status==='Proses Pengerjaan').length],['Selesai',d.orders.filter(o=>o.status==='Selesai').length]];$('#page').innerHTML=`<div class="sectionhead"><div><span class="eyebrow" style="color:#c28df3">ADMIN WORKSPACE</span><h1 style="font-size:29px;margin-top:7px">Kelola layanan. Bantu lebih banyak.</h1><p>Semua perubahan tersimpan pada Spreadsheet yang terhubung.</p></div><button class="btn small" data-action="refresh">${icon('refresh',16)} Muat ulang</button></div><div class="stats six">${metrics.map(x=>`<div class="stat"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="tabs">${[['overview','Dashboard'],['products','Kelola Jasa'],['categories','Kategori'],['orders','Pesanan'],['customers','Pelanggan'],['settings','Pengaturan']].map(t=>`<button class="chip ${S.adminTab===t[0]?'active':''}" data-action="adminTab" data-tab="${t[0]}" aria-pressed="${S.adminTab===t[0]}">${t[1]}</button>`).join('')}</div><div id="adminPane" class="tabcontent"></div>`;renderAdminPane();}
function renderAdminPane(){const d=S.admin,el=$('#adminPane');if(S.adminTab==='overview'){el.innerHTML=`<div class="profile-grid"><section class="panel"><h2 style="font-size:19px;margin-bottom:18px">Perlu ditindaklanjuti</h2><div class="stack">${d.orders.filter(o=>!['Selesai','Dibatalkan'].includes(o.status)).slice(0,5).map(o=>`<div class="row spread wrap"><div><strong class="tiny">${esc(o.title)}</strong><p class="tiny muted" style="margin:4px 0">${esc(o.id)} · ${esc(o.status)}</p></div><button class="btn small" data-action="editOrder" data-id="${esc(o.id)}">Kelola</button></div>`).join('')||'<p class="tiny muted">Belum ada pesanan yang perlu ditindaklanjuti.</p>'}</div></section><section class="panel"><h2 style="font-size:19px;margin-bottom:16px">Katalog siap berkembang</h2><p class="tiny muted">Tambahkan layanan, paket harga, serta preview pekerjaan agar pelanggan mudah memilih. Produk nonaktif tetap tersimpan dan bisa diterbitkan kembali.</p><button class="btn primary" data-action="editProduct">${icon('plus',16)} Tambah Layanan</button><p class="statnote" style="margin-top:20px">Populer diurutkan berdasarkan jumlah pesanan tersimpan, bukan rating atau ulasan buatan.</p></section></div>`;}
else if(S.adminTab==='products'){el.innerHTML=`<div class="sectionhead"><h2 style="font-size:18px">Kelola Layanan (${d.products.length})</h2><button class="btn primary small" data-action="editProduct">${icon('plus',16)} Tambah Jasa</button></div><div class="adminlist">${d.products.map(p=>`<article class="adminitem"><div><span class="badge ${p.active?'green':''}">${p.active?'Aktif':'Nonaktif'}</span> ${p.badge?`<span class="badge">${esc(p.badge)}</span>`:''}<h3>${esc(p.title)}</h3><p>${esc(p.category)} · ${rupiah(p.price)} · ${p.packages?.length||0} paket · ${p.previews?.length||0} preview</p></div><div class="row wrap"><button class="btn small" data-action="editProduct" data-id="${esc(p.id)}">Edit</button><button class="btn danger small" data-action="deleteProductPrompt" data-id="${esc(p.id)}">Hapus</button></div></article>`).join('')||'<div class="empty">Belum ada layanan.</div>'}</div>`;}
else if(S.adminTab==='orders'){el.innerHTML=`<div class="admin-toolbar"><input id="adminOrderSearch" type="search" placeholder="Cari ID pesanan atau nama pelanggan…" aria-label="Cari pesanan" value="${esc(S.adminSearch)}"><select id="adminOrderStatus" aria-label="Filter status"><option value="all">Semua status</option>${['Belum Dibayar','Proses Pengerjaan','Selesai'].map(s=>`<option ${s===S.adminStatus?'selected':''}>${s}</option>`).join('')}</select></div><div class="adminlist" id="adminOrderList"></div>`;renderAdminOrders();}
else if(S.adminTab==='customers'){el.innerHTML=`<div class="sectionhead"><h2 style="font-size:19px">Pelanggan</h2><span class="count">${d.customers.length} akun</span></div><input id="customerSearch" type="search" aria-label="Cari pelanggan" placeholder="Cari nama atau nomor WhatsApp…" value="${esc(S.customerSearch)}" style="margin-bottom:18px"><div class="adminlist" id="customerList"></div>`;renderCustomers();}
else if(S.adminTab==='categories'){el.innerHTML=`<div class="sectionhead"><h2 style="font-size:19px">Kategori Layanan</h2><button class="btn primary small" data-action="editCategory">${icon('plus',15)} Tambah Kategori</button></div><div class="adminlist">${d.categories.map(c=>`<article class="adminitem"><div class="row"><span class="valueicon">${icon(c.icon||'grid',20)}</span><div><h3>${esc(c.name)}</h3><p>${c.active===true||String(c.active)==='true'?'Aktif':'Nonaktif'} · ${d.products.filter(p=>p.category===c.name).length} layanan</p></div></div><div class="row"><button class="btn small" data-action="editCategory" data-id="${esc(c.id)}">Edit</button><button class="btn danger small" data-action="deleteCategoryPrompt" data-id="${esc(c.id)}">Hapus</button></div></article>`).join('')}</div>`;}
else settingsPage();}
function renderAdminOrders(){const d=S.admin;const filtered=d.orders.filter(o=>{const u=d.customers.find(x=>x.id===o.userId);return(S.adminStatus==='all'||o.status===S.adminStatus)&&[o.id,u?.name,o.title].join(' ').toLowerCase().includes(S.adminSearch.toLowerCase());});$('#adminOrderList').innerHTML=filtered.map(o=>{const u=d.customers.find(x=>x.id===o.userId);const wa=whatsappLink('Halo '+(u?.name||'')+', kami ingin membahas pesanan '+o.id+'.',u?.phone);return `<article class="adminitem"><div><span class="tiny muted">${esc(o.id)}</span><h3>${esc(o.title)} · ${esc(o.packageName||'Basic')}</h3><p>${esc(u?.name||o.userId)} · ${esc(u?.phone||'')} · ${rupiah(o.price)}</p><p>Deadline ${esc(o.deadline)}</p><div class="row wrap" style="margin-top:8px"><span class="badge">${esc(o.status)}</span></div></div><div class="row wrap">${wa?`<a class="btn small" href="${esc(wa)}" target="_blank" rel="noopener noreferrer">WhatsApp</a>`:''}<button class="btn small" data-action="editOrder" data-id="${esc(o.id)}">Kelola Pesanan</button></div></article>`;}).join('')||'<div class="empty"><h3>Belum ada pesanan yang cocok</h3><p>Ubah pencarian atau filter status.</p></div>';}
function renderCustomers(){const d=S.admin;const list=d.customers.filter(u=>[u.name,u.phone].join(' ').toLowerCase().includes(S.customerSearch.toLowerCase()));$('#customerList').innerHTML=list.map(u=>`<article class="adminitem"><div><h3>${esc(u.name)} ${u.role==='admin'?'<span class="badge">Admin</span>':''}</h3><p>${esc(u.phone)} · ${d.orders.filter(o=>o.userId===u.id).length} pesanan</p><p>Terdaftar ${u.createdAt?new Date(u.createdAt).toLocaleDateString('id-ID'):'—'}</p></div><a class="btn small" href="${esc(whatsappLink('Halo '+u.name+', kami dari JASAhub.id.',u.phone))}" target="_blank" rel="noopener noreferrer">Hubungi Pelanggan</a></article>`).join('')||'<div class="empty">Pelanggan tidak ditemukan.</div>';}
function darkSettingsPage(){const d=S.admin.settings;$('#adminPane').innerHTML=`<section class="panel"><h2 style="font-size:19px;margin-bottom:20px">Identitas & Pengaturan Website</h2><form id="settingsForm" class="formgrid">${[['siteName','Nama website',80],['siteDescription','Deskripsi singkat',300],['heroTitle','Judul hero',150],['heroDescription','Deskripsi hero',400],['footerText','Teks footer',300],['contactInfo','Informasi kontak',500]].map(([key,label,max])=>`<label class="field ${key.includes('Description')?'full':''}">${label}<input name="${key}" maxlength="${max}" value="${esc(d[key]||'')}"></label>`).join('')}<label class="field full">URL logo kustom (opsional)<input name="logoUrl" id="logoUrlInput" type="url" value="${(d.logoUrl?.startsWith('data:')||d.logoUrl?.startsWith('drive:'))?'':esc(d.logoUrl||'')}" placeholder="https://…"><small>Kosong = logo asli yang kamu kirim. Logo asli sudah tertanam di HTML.</small></label><label class="field full">Unggah logo kustom<input id="logoUpload" type="file" accept="image/png,image/jpeg,image/webp"><small>Logo disimpan di Drive admin. Simpan Pengaturan setelah unggah.</small></label><label class="field">Nomor WhatsApp admin<input name="whatsapp" type="tel" required value="${esc(d.whatsapp||'')}" placeholder="6281234567890"></label><label class="field full">Instruksi pembayaran<textarea name="paymentInfo" minlength="5" maxlength="2000" required>${esc(d.paymentInfo||'')}</textarea><small>Informasi ini terlihat publik. Pembayaran diverifikasi manual.</small></label><div class="error full" id="settingsError" role="alert" tabindex="-1"></div><div class="formfoot full"><button class="btn" type="button" data-action="resetLogo">Gunakan Logo Asli</button><button type="submit" class="btn primary">Simpan Pengaturan</button></div></form><p class="settingsnote" style="margin-top:20px">Gunakan promoteAdmin di Apps Script untuk memberikan akses administrator. Tidak ada password pelanggan yang ditampilkan di dashboard.</p></section>`;S.customLogo=d.logoUrl||'';}
function editCategory(id){const c=S.admin.categories.find(x=>x.id===id)||{name:'',icon:'grid',active:true};showModal(id?'Edit kategori':'Tambah kategori',`<form id="categoryForm" data-id="${esc(id||'')}" class="stack"><label class="field">Nama kategori<input name="name" minlength="2" maxlength="60" required value="${esc(c.name)}"></label><label class="field">Ikon SVG<select name="icon">${['doc','slide','chart','pen','cad','book','grid','layers','settings','user','message'].map(key=>`<option value="${key}" ${key===c.icon?'selected':''}>${key}</option>`).join('')}</select></label><label class="check"><input name="active" type="checkbox" ${c.active===true||String(c.active)==='true'?'checked':''}> Kategori aktif</label><div class="error" id="categoryError" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">Simpan Kategori</button></form>`,true);}
function updatePackageDeleteButtons(){
 const form=$('#productForm');if(!form)return;
 const count=form.querySelectorAll('.pkg-editor').length;
 form.querySelectorAll('[data-action="removePackage"]').forEach(b=>{b.disabled=count<=1;b.title=count<=1?'Minimal satu paket harus tersedia':'';});
 const undo=$('#undoPackage');if(undo)undo.hidden=!S.removedPackages?.length;
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action]');if(!button)return;
 if(button.dataset.action==='removePackage'){
  const section=button.closest('.pkg-editor'),form=$('#productForm');
  if(!section||!form||form.querySelectorAll('.pkg-editor').length<=1)return;
  S.removedPackages.push(section);section.remove();updatePackageDeleteButtons();
  $('#packageEditNotice').textContent='Paket '+section.dataset.packageName+' dihapus dari form. Tekan Simpan Layanan untuk menerapkan.';
  $('#undoPackage').focus();
 }else if(button.dataset.action==='undoPackage'){
  const section=S.removedPackages?.pop(),notice=$('#packageEditNotice');if(!section||!notice)return;
  const form=$('#productForm');const next=Array.from(form.querySelectorAll('.pkg-editor')).find(x=>Number(x.dataset.packageIndex)>Number(section.dataset.packageIndex));
  if(next)next.before(section);else notice.parentElement.before(section);
  updatePackageDeleteButtons();notice.textContent='Paket '+section.dataset.packageName+' dipulihkan. Perubahan belum disimpan.';
  section.querySelector('input').focus();
 }
});
function editProduct(id){const p=S.admin.products.find(x=>x.id===id)||{title:'',category:S.admin.categories.find(c=>c.active)?.name||'',description:'',shortDescription:'',price:25000,days:2,revisions:2,thumbnail:'',active:false,featured:false,badge:'',previews:[]};const packs=p.packages?.length?p.packages:['Basic','Standard','Premium'].map((name,i)=>({name,price:25000*(i+1),days:2+i,revisions:2+i,features:'Lingkup pekerjaan sesuai deskripsi\nFile hasil digital'}));S.removedPackages=[];S.editingProductId=id||'';showModal(id?'Edit layanan':'Tambah layanan baru',`<form id="productForm" data-id="${esc(id||'')}" class="formgrid"><label class="field full">Judul jasa<input name="title" minlength="3" maxlength="120" required value="${esc(p.title)}"></label><label class="field">Kategori<select name="category" required>${S.admin.categories.filter(c=>c.active===true||String(c.active)==='true').map(c=>`<option ${p.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Badge katalog<select name="badge"><option value="">Tanpa badge</option>${['Populer','Terbaru','Unggulan'].map(t=>`<option ${t===p.badge?'selected':''}>${t}</option>`).join('')}</select></label><label class="field full">Deskripsi singkat<textarea name="shortDescription" minlength="5" maxlength="250" style="min-height:75px" required>${esc(p.shortDescription||p.description.slice(0,180))}</textarea></label><label class="field full">Deskripsi lengkap & lingkup<textarea name="description" minlength="10" maxlength="5000" required>${esc(p.description)}</textarea></label><label class="field full">URL thumbnail (opsional)<input id="thumbnailUrl" name="thumbnail" type="url" value="${(p.thumbnail?.startsWith('data:')||p.thumbnail?.startsWith('drive:'))?'':esc(p.thumbnail)}" placeholder="https://…"></label><label class="field full">Unggah thumbnail<input id="thumbnailFile" type="file" accept="image/jpeg,image/png,image/webp"><small>Maks. 5 MB. Diunggah ke Drive admin. Kosong menggunakan ilustrasi bawaan.</small></label><div id="thumbnailPreview" class="full"></div><h3 class="full" style="font-size:17px;margin:10px 0">Paket layanan</h3>${packs.map((x,i)=>`<section class="pkg-editor full" data-package-name="${esc(x.name)}" data-package-index="${i}"><div class="row spread wrap"><h3>${esc(x.name)}</h3><button type="button" class="btn danger small" data-action="removePackage" aria-label="Hapus paket ${esc(x.name)}">Hapus Paket</button></div><div class="formgrid"><label class="field">Harga (Rp)<input name="pkgPrice${i}" type="number" min="1000" max="100000000" step="1" required value="${x.price}"></label><label class="field">Estimasi (hari)<input name="pkgDays${i}" type="number" min="1" max="365" step="1" required value="${x.days}"></label><label class="field">Jumlah revisi<input name="pkgRevisions${i}" type="number" min="0" max="20" step="1" required value="${x.revisions}"></label><label class="field full">Fitur & lingkup paket (satu per baris)<textarea name="pkgFeatures${i}" minlength="5" maxlength="1200" required>${esc(x.features)}</textarea></label></div></section>`).join('')}<div class="full"><p class="tiny muted" id="packageEditNotice" role="status">Minimal satu paket. Penghapusan berlaku setelah Simpan Layanan.</p><button type="button" class="btn small" id="undoPackage" data-action="undoPackage" hidden>Urungkan hapus paket</button></div><label class="check"><input name="active" type="checkbox" ${p.active?'checked':''}> Terbitkan jasa</label><label class="check"><input name="featured" type="checkbox" ${p.featured?'checked':''}> Tampilkan sebagai unggulan</label><div class="error full" id="productError" role="alert" tabindex="-1"></div><div class="formfoot full savebar"><button class="btn" type="button" data-action="close">Tutup</button><button class="btn primary" type="submit">Simpan Layanan</button></div></form><div class="splitline"></div><section><h3 style="font-size:18px;margin-bottom:14px">Galeri Preview (opsional)</h3>${id?`<p class="tiny muted">Simpan perubahan layanan sebelum mengelola galeri. Maksimal 24 gambar per jasa. Gunakan tombol panah untuk mengubah urutan.</p><label class="field">Unggah satu atau beberapa preview<input id="previewFiles" type="file" multiple accept="image/png,image/jpeg,image/webp"></label><form id="previewUrlForm" data-product="${esc(id)}" class="stack" style="margin:18px 0"><label class="field">Atau URL gambar HTTPS<input name="image" type="url" required maxlength="2000"></label><label class="field">Keterangan (opsional)<input name="caption" maxlength="120"></label><div id="previewUrlError" class="error" role="alert" tabindex="-1"></div><button class="btn" type="submit">Tambahkan Preview URL</button></form><div id="galleryEditor" class="gallery-editor"></div><div id="galleryError" class="error" role="alert" tabindex="-1"></div>`:'<p class="tiny muted">Simpan jasa terlebih dahulu. Setelah tersimpan, form ini akan terbuka kembali untuk menambahkan preview.</p>'}</section>`);S.thumbnail=p.thumbnail||'';showThumbnailPreview();updatePackageDeleteButtons();if(id)renderGalleryEditor();}
function renderGalleryEditor(){const product=S.admin.products.find(x=>x.id===S.editingProductId);if(!product||!$('#galleryEditor'))return;$('#galleryEditor').innerHTML=(product.previews||[]).map((x,i)=>`<div class="gallery-edititem"><img src="${esc(safeUrl(x.image,true))}" alt="Preview ${i+1}" referrerpolicy="no-referrer"><span class="tiny">${i+1}. ${esc(x.caption||'Preview')}</span><div class="row"><button class="iconbtn" data-action="previewUp" data-id="${esc(x.id)}" aria-label="Pindahkan preview ${i+1} ke atas" ${i===0?'disabled':''}>${icon('arrow',16).replace('<svg ','<svg style="transform:rotate(-90deg)" ')}</button><button class="iconbtn" data-action="previewDown" data-id="${esc(x.id)}" aria-label="Pindahkan preview ${i+1} ke bawah" ${i===product.previews.length-1?'disabled':''}>${icon('arrow',16).replace('<svg ','<svg style="transform:rotate(90deg)" ')}</button><button class="btn danger small" data-action="deletePreviewPrompt" data-id="${esc(x.id)}">Hapus</button></div></div>`).join('')||'<p class="tiny muted">Belum ada preview. Galeri publik otomatis disembunyikan.</p>';}
async function syncAdmin(){S.admin=await api('adminData');S.categories=S.admin.categories.filter(x=>x.active===true||String(x.active).toLowerCase()==='true');S.products=S.admin.products.filter(p=>p.active&&S.categories.some(c=>c.name===p.category));S.settings=S.admin.settings;S.loadError=false;updateBrand();}
function deletionPrompt(kind,id){const title={Product:'Hapus layanan?',Category:'Hapus kategori?',Preview:'Hapus preview?'}[kind];const note=kind==='Product'?'Layanan, paket, dan preview akan dihapus. Riwayat pesanan tetap tersimpan.':kind==='Category'?'Kategori yang masih memiliki layanan harus dikosongkan dahulu.':'Gambar preview akan dihapus dari galeri.';showModal(title,`<p class="muted tiny">${note}</p><form id="deleteForm" data-kind="${kind}" data-id="${esc(id)}"><div class="error" id="deleteError" role="alert" tabindex="-1"></div><div class="formfoot"><button class="btn" data-action="close" type="button">Batal</button><button class="btn danger" type="submit">Ya, Hapus</button></div></form>`,true);}
async function route(){const version=++S.routeVersion;let hash=location.hash.slice(1)||'catalog';if(hash==='main')hash='catalog';const [page,arg]=hash.split('/');const name={catalog:'Eksplor Jasa',service:'Detail Layanan',orders:'Pesanan Saya',admin:'Dashboard Admin',profile:'Akun Saya',help:'Cara Order & FAQ'}[page]||'Eksplor Jasa';document.title=name+' — '+(S.settings.siteName||'JASAhub.id');document.body.classList.toggle('workspace',['admin','orders','profile'].includes(page)&&!!S.user);$('#breadcrumb').textContent=name;document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===page);if(a.dataset.route===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('#adminSubnav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+hash));closeNav();setNotice();if(page==='admin'&&['overview','products','categories','orders','customers','settings'].includes(arg))S.adminTab=arg;if(page==='orders')await ordersPage(version);else if(page==='admin')await adminPage(version);else if(page==='profile')profilePage();else if(page==='service')renderService(decodeURIComponent(arg||''));else if(page==='help')help();else catalog();hydrate();updateBrand();updateMobileChrome();if(page==='catalog'&&arg==='all')setTimeout(()=>$('#catalogSection')?.scrollIntoView(),30);}
const helpBase=legacyHelp;
function help(){helpBase();const p=$('#page');p.innerHTML=p.innerHTML.replace('kirim brief, lalu ikuti instruksi pembayaran.','kirim brief, lalu lanjutkan konfirmasi melalui WhatsApp admin.').replace('Katalog, detail layanan, dan harga bisa dilihat tanpa akun.','Katalog, detail layanan, preview, dan paket bisa dilihat tanpa akun.');}
document.addEventListener('input',e=>{if(e.target.id==='adminOrderSearch'){S.adminSearch=e.target.value;renderAdminOrders();}if(e.target.id==='customerSearch'){S.customerSearch=e.target.value;renderCustomers();}if(e.target.id==='logoUrlInput')S.customLogo=e.target.value.trim();});
document.addEventListener('change',async e=>{if(e.target.id==='priceRange'){S.priceRange=e.target.value;renderProducts();}if(e.target.id==='adminOrderStatus'){S.adminStatus=e.target.value;renderAdminOrders();}if(e.target.name==='chosenPackage'){S.package=S.selected.packages.find(x=>x.id===e.target.value);document.querySelectorAll('.package').forEach(el=>el.classList.toggle('selected',$('input',el).value===S.package.id));updateMobileChrome();}if(e.target.id==='logoUpload'&&e.target.files[0]){const b=$('#settingsForm button[type=submit]');b.disabled=true;try{S.customLogo=await uploadImage(e.target.files[0],'logo');$('#logoUrlInput').value='';toast('Logo siap disimpan.');}catch(err){$('#settingsError').textContent=err.message;}finally{b.disabled=false;}}if(e.target.id==='previewFiles'){const input=e.target,files=Array.from(input.files);input.disabled=true;$('#galleryError').textContent='';try{for(const file of files){const image=await uploadImage(file,'preview');await api('savePreview',{productId:S.editingProductId,image,caption:file.name.slice(0,120)});}toast('Preview berhasil ditambahkan.');}catch(err){$('#galleryError').textContent=err.message+' Gambar yang berhasil diunggah tetap tersimpan.';}finally{try{await syncAdmin();renderGalleryEditor();}catch(err){$('#galleryError').textContent=err.message;}input.disabled=false;input.value='';}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action;if(a==='categoryJump'){S.category=b.dataset.name;S.priceRange='all';S.search='';if(location.hash==='#catalog'||!location.hash){catalog();$('#catalogSection').scrollIntoView();}else{location.hash='catalog/all';}}
else if(a==='resetAll'){S.search='';S.category='Semua Jasa';S.priceRange='all';$('#search').value='';$('#priceRange').value='all';renderFilters();renderProducts();}
else if(a==='packageCheckout'){S.package=S.selected.packages.find(x=>x.id===b.dataset.id)||S.package;renderPackageCards();updateMobileChrome();checkout();}
else if(a==='galleryNext'||a==='galleryPrev'){S.galleryIndex+=a==='galleryNext'?1:-1;renderGallery();}
else if(a==='galleryAt'){S.galleryIndex=Number(b.dataset.index);renderGallery();}
else if(a==='galleryZoom'){const x=S.selected.previews[S.galleryIndex];showModal('Preview '+(S.galleryIndex+1),x.demo?demoPreview(x):`<img class="zoom-image" src="${esc(safeUrl(x.image,true))}" alt="${esc(x.caption||'Preview hasil')}" referrerpolicy="no-referrer">`);}
else if(a==='galleryFull'){const el=$('#galleryDisplay');if(el.requestFullscreen)await el.requestFullscreen();else toast('Layar penuh tidak didukung browser ini. Gunakan tombol perbesar.');}
else if(a==='copyOrderMessage'){const text=$('#waMessage').value;try{await navigator.clipboard.writeText(text);toast('Pesan berhasil disalin.');}catch(_){$('#waMessage').select();toast('Pilih Salin dari menu perangkat untuk menyalin pesan.');}}
else if(a==='viewOrders'){$('#modal').close();location.hash='orders';route();}
else if(a==='editCategory')editCategory(b.dataset.id);
else if(a==='deleteProductPrompt')deletionPrompt('Product',b.dataset.id);
else if(a==='deleteCategoryPrompt')deletionPrompt('Category',b.dataset.id);
else if(a==='deletePreviewPrompt')deletionPrompt('Preview',b.dataset.id);
else if(a==='previewUp'||a==='previewDown'){b.disabled=true;try{const p=S.admin.products.find(x=>x.id===S.editingProductId);const ids=p.previews.map(x=>x.id);const from=ids.indexOf(b.dataset.id),to=from+(a==='previewUp'?-1:1);[ids[from],ids[to]]=[ids[to],ids[from]];await api('reorderPreviews',{productId:p.id,ids});await syncAdmin();renderGalleryEditor();}finally{if(b.isConnected)b.disabled=false;}}
else if(a==='resetLogo'){S.customLogo='';$('#logoUrlInput').value='';$('#logoUpload').value='';toast('Logo asli akan digunakan setelah disimpan.');}
}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;const d=Object.fromEntries(new FormData(f));
if(f.id==='profileForm'){e.preventDefault();await formTask(f,'#profileError',async()=>{S.user=await api('updateProfile',d);topbar();await route();toast('Profil berhasil diperbarui.');});}
if(f.id==='passwordForm'){e.preventDefault();await formTask(f,'#passwordError',async()=>{const challenge=await api('challenge',{phone:S.user.username||S.user.phone});let oldKey;if(challenge.legacy)oldKey=await deriveKey(d.oldPassword,challenge.salt);const result=await api('changePassword',{oldPassword:d.oldPassword,newPassword:d.newPassword,oldKey});S.token=result.token;persistSessionToken(S.token);f.reset();toast('Password berhasil diubah. Sesi lain telah diakhiri.');});}
if(f.id==='previewUrlForm'){e.preventDefault();await formTask(f,'#previewUrlError',async()=>{await api('savePreview',{...d,productId:f.dataset.product});await syncAdmin();renderGalleryEditor();f.reset();toast('Preview ditambahkan.');});}
if(f.id==='deleteForm'){e.preventDefault();await formTask(f,'#deleteError',async()=>{const editId=S.editingProductId;await api('delete'+f.dataset.kind,{id:f.dataset.id});await syncAdmin();if(f.dataset.kind==='Preview'){editProduct(editId);}else{$('#modal').close();renderAdmin();}toast('Berhasil dihapus.');});}
});

/* QRIS manual payment / Google Drive media / exact three-status workflow. */
const MEDIA_CACHE=new Map(),MEDIA_PROMISES=new Map();let MEDIA_ACTIVE=0;const MEDIA_QUEUE=[];
function driveRefId(ref){const m=String(ref||'').match(/^drive:([A-Za-z0-9_-]{10,100})$/);return m?m[1]:'';}
function mediaUrl(ref){const id=driveRefId(ref);if(!id)return '';return MEDIA_CACHE.get(id)||'/api/media?id='+encodeURIComponent(id);}
function queueMedia(id){if(MEDIA_CACHE.has(id))return Promise.resolve(MEDIA_CACHE.get(id));if(MEDIA_PROMISES.has(id))return MEDIA_PROMISES.get(id);const p=new Promise((resolve,reject)=>{MEDIA_QUEUE.push({id,resolve,reject});pumpMedia();});MEDIA_PROMISES.set(id,p);return p;}
async function pumpMedia(){if(MEDIA_ACTIVE>=2||!MEDIA_QUEUE.length)return;const job=MEDIA_QUEUE.shift();MEDIA_ACTIVE++;try{const result=await api('media',{id:job.id});if(!/^data:image\/(png|jpeg|webp);base64,/.test(result.data))throw Error('Format gambar tidak valid.');MEDIA_CACHE.set(job.id,result.data);job.resolve(result.data);}catch(e){MEDIA_PROMISES.delete(job.id);job.reject(e);}finally{MEDIA_ACTIVE--;pumpMedia();}}
async function resolveImage(img){const m=String(img.getAttribute('src')||'').match(/#drive=([A-Za-z0-9_-]+)$/);if(!m||img.dataset.resolving)return;img.dataset.resolving='1';try{const data=await queueMedia(m[1]);if(img.isConnected){img.src=data;img.removeAttribute('data-resolving');}}catch(e){if(img.isConnected){img.alt='Gambar belum dimuat: '+e.message;img.title=e.message;if(img.dataset.qris!==undefined){const error=$('#qrisMediaError');if(error)error.textContent='QRIS belum dapat dimuat. Coba muat ulang atau hubungi admin sebelum membayar.';}}}}
const MEDIA_OBSERVER=typeof IntersectionObserver!=='undefined'?new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting){MEDIA_OBSERVER.unobserve(x.target);resolveImage(x.target);}}),{rootMargin:'300px'}):null;
function scanMedia(){document.querySelectorAll('img[src*="#drive="]:not([data-observed])').forEach(img=>{img.dataset.observed='1';if(MEDIA_OBSERVER)MEDIA_OBSERVER.observe(img);else resolveImage(img);});}
const MEDIA_MUTATIONS=new MutationObserver(scanMedia);MEDIA_MUTATIONS.observe(document.body,{childList:true,subtree:true});
function qrisPanel(){const src=safeUrl(S.settings.qrisImage,true);return `<section class="qris-panel"><div><span class="badge">QRIS · Verifikasi manual</span><h3 style="margin:12px 0 8px">Bayar sesuai nominal pesanan</h3><p class="tiny muted">Periksa nama merchant pada aplikasi pembayaran. Simpan bukti, lalu lampirkan sendiri di WhatsApp admin. Status tetap <strong>Belum Dibayar</strong> sampai admin memverifikasi dana.</p></div>${src?`<div class="qris-frame"><img src="${esc(src)}" alt="QRIS pembayaran JASAhub.id dari admin" data-qris width="700" height="900" referrerpolicy="no-referrer"></div><button class="btn small" type="button" data-action="zoomQris">${icon('search',16)} Perbesar QRIS</button>`:'<div class="error">Admin belum mengunggah QRIS. Hubungi admin sebelum membayar.</div>'}<p class="tiny muted" style="white-space:pre-wrap;margin-top:12px">${esc(S.settings.paymentInfo||'')}</p><div id="qrisMediaError" class="error" role="alert"></div></section>`;}
function checkout(){if(!S.selected)return;if(!CONFIG.API_URL){toast('Hubungkan backend sebelum checkout.');return;}if(!S.user){auth('login',true);return;}const p=S.selected,x=S.package||p.packages[0];const min=localDate(new Date(Date.now()+x.days*86400000));showModal('Checkout · Pembayaran QRIS',`<div class="checkoutsummary"><h3>${esc(p.title)}</h3><p class="tiny muted">Paket ${esc(x.name)} · ${x.days} hari · ${x.revisions} revisi</p><div class="row spread"><span>Total pembayaran</span><strong style="font-size:25px;color:#d6a4ff">${rupiah(x.price)}</strong></div></div><form id="checkoutForm" class="stack" data-request="${randomHex()}"><div class="row spread wrap tiny"><span>Nama: <strong>${esc(S.user.name)}</strong></span><span>WhatsApp: ${esc(S.user.phone)}</span></div><label class="field">Deadline<input name="deadline" type="date" min="${min}" required><small>Jadwal dikonfirmasi setelah pembayaran dan bahan lengkap.</small></label><label class="field">Detail kebutuhan<textarea name="brief" minlength="15" maxlength="5000" required></textarea></label><label class="field">Tautan bahan (opsional)<input type="url" name="materialUrl" maxlength="2000" placeholder="https://drive.google.com/…"></label><label class="field">Catatan tambahan (opsional)<textarea name="customerNote" maxlength="2000" style="min-height:75px"></textarea></label>${qrisPanel()}<label class="check"><input type="checkbox" required> Saya sudah membaca lingkup paket dan ketentuan layanan.</label><p class="tiny muted">Simpan pesanan terlebih dahulu agar mendapatkan ID untuk bukti pembayaran. Menekan tombol berikut tidak menandai pembayaran sebagai lunas.</p><div id="checkoutError" class="error" role="alert" tabindex="-1"></div><button type="submit" class="btn primary">Simpan Pesanan & Lihat Pembayaran ${icon('arrow',16)}</button></form>`);scanMedia();}
function orderMessage(order){return `Halo Admin JASAhub.id, saya ingin mengirim bukti pembayaran QRIS.\n\nID pesanan: ${order.id}\nNama: ${S.user.name}\nWhatsApp: ${S.user.phone||'-'}\nJasa: ${order.title}\nPaket: ${order.packageName||'Basic'}\nNominal: ${rupiah(order.price)}\nDeadline: ${order.deadline}\n\nSaya akan melampirkan bukti transfer secara manual di chat ini. Mohon periksa bukti dan pastikan dana masuk.\n\nDetail kebutuhan:\n${order.brief}\nBahan: ${order.materialUrl||'-'}\nCatatan: ${order.customerNote||'-'}`;}
function checkoutSuccess(order){S.paymentOrder=order;const message=orderMessage(order);showModal('Pesanan tersimpan · Bayar dengan QRIS',`<span class="badge orange">Belum Dibayar</span><div class="checkoutsummary" style="margin-top:18px"><span class="eyebrow">${esc(order.id)}</span><h3>${esc(order.title)}</h3><p class="tiny muted">${esc(order.packageName||'Basic')} · ${esc(S.user.name)}</p><strong style="font-size:27px;color:#d6a4ff">${rupiah(order.price)}</strong></div>${qrisPanel()}<div class="splitline"></div><h3 style="font-size:17px;margin-bottom:10px">Sudah membayar?</h3><p class="tiny muted">Tekan tombol berikut, lalu pilih foto bukti transfer dan tekan Kirim di WhatsApp. Website tidak dapat melampirkan atau memastikan bukti terkirim secara otomatis.</p><textarea id="waMessage" class="copyarea" readonly aria-label="Pesan bukti pembayaran">${esc(message)}</textarea><div class="error" id="proofError" role="alert" tabindex="-1"></div><div class="formfoot"><button class="btn" data-action="copyOrderMessage">Salin Pesan</button><button class="btn primary" data-action="sendProof">${icon('message',17)} Kirim Bukti Pembayaran</button><button class="btn" data-action="viewOrders">Lihat Pesanan</button></div><div id="proofFallback"></div>`);scanMedia();}
function orderCard(o){const result=safeUrl(o.resultUrl);const material=safeUrl(o.materialUrl);return `<article class="ordercard"><div class="row spread wrap"><span class="tiny muted">${esc(o.id)}</span><span class="badge ${o.status==='Selesai'?'green':o.status==='Belum Dibayar'?'orange':''}">${esc(o.status)}</span></div><h3>${esc(o.title)}</h3><p class="tiny muted">Paket ${esc(o.packageName||'Basic')} · ${new Date(o.createdAt).toLocaleDateString('id-ID')}</p><div class="statusrail" aria-hidden="true">${['Belum Dibayar','Proses Pengerjaan','Selesai'].map((s,i)=>`<span class="${i<=['Belum Dibayar','Proses Pengerjaan','Selesai'].indexOf(o.status)?'done':''}"></span>`).join('')}</div><div class="orderbody"><div><span class="label">Kebutuhan</span><p>${esc(o.brief)}</p>${o.customerNote?`<p class="tiny muted">Catatan: ${esc(o.customerNote)}</p>`:''}${material?`<a class="tiny" href="${esc(material)}" target="_blank" rel="noopener noreferrer">Buka bahan</a>`:''}${o.adminNote?`<p style="margin-top:14px"><strong>Catatan admin:</strong><br>${esc(o.adminNote)}</p>`:''}</div><div><span class="label">Detail pesanan</span><p>Total <strong>${rupiah(o.price)}</strong></p><p>Deadline ${esc(o.deadline)}</p><p>Sisa revisi ${Number(o.revisions)}</p>${o.paymentVerifiedAt?`<p class="tiny muted">Pembayaran diverifikasi ${new Date(o.paymentVerifiedAt).toLocaleString('id-ID')}</p>`:'<p class="tiny muted">Bukti yang dikirim tetap menunggu pemeriksaan admin.</p>'}</div></div><div class="orderactions">${o.status==='Belum Dibayar'?`<button class="btn primary small" data-action="payQris" data-id="${esc(o.id)}">Bayar QRIS / Kirim Bukti</button>`:''}${result?`<a class="btn primary small" href="${esc(result)}" target="_blank" rel="noopener noreferrer">Buka Hasil ${icon('arrow',15)}</a>`:''}${o.status==='Proses Pengerjaan'&&result&&Number(o.revisions)>0?`<button class="btn small" data-action="revision" data-id="${esc(o.id)}">Minta Revisi</button>`:''}<button class="btn ghost small" data-action="contact">Hubungi Admin</button></div></article>`;}
async function ordersPage(version){if(!S.user){$('#page').innerHTML='<div class="empty"><h1 style="font-size:25px">Pesanan Saya</h1><p>Masuk untuk melihat pesanan, pembayaran, dan hasil.</p><button class="btn primary" data-action="auth" data-mode="login">Masuk</button></div>';return;}$('#page').innerHTML=busy();try{const orders=await api('orders');if(version!==S.routeVersion)return;S.orders=orders;$('#page').innerHTML=`<div class="sectionhead"><div><h1 style="font-size:26px">Pesanan Saya</h1><p>Bayar QRIS, kirim bukti melalui WhatsApp, lalu pantau pengerjaannya.</p></div><button class="btn small" data-action="refresh">${icon('refresh',16)} Muat ulang</button></div><div class="stack">${orders.length?orders.map(orderCard).join(''):'<div class="empty"><h3>Belum ada pesanan</h3><a href="#catalog" class="btn primary">Jelajahi Jasa</a></div>'}</div><p class="tiny muted" style="margin:24px 0">Hanya admin yang mengubah status. Status tetap Belum Dibayar ketika bukti sedang diperiksa.</p>`;}catch(e){if(version===S.routeVersion)pageError(e);}}
function editOrder(id){const o=S.admin.orders.find(x=>x.id===id);if(!o)return;const u=S.admin.customers.find(x=>x.id===o.userId);showModal('Kelola Pesanan · Verifikasi Manual',`<div class="checkoutsummary"><h3>${esc(o.title)}</h3><p class="tiny muted">${esc(o.id)} · Paket ${esc(o.packageName||'Basic')}<br>${esc(u?.name||'')} · ${esc(u?.phone||'')}</p><strong style="font-size:24px;color:#d6a4ff">${rupiah(o.price)}</strong></div><p class="detailtext">${esc(o.brief)}</p>${safeUrl(o.materialUrl)?`<a href="${esc(safeUrl(o.materialUrl))}" class="btn small" target="_blank" rel="noopener noreferrer">Buka bahan</a>`:''}<p class="tiny muted">Deadline ${esc(o.deadline)} · ${esc(o.paymentReference||'Bukti transfer diperiksa melalui WhatsApp admin.')}</p><form id="orderForm" data-id="${esc(id)}" class="stack"><label class="field">Status pesanan<select name="status">${['Belum Dibayar','Proses Pengerjaan','Selesai'].map(s=>`<option ${s===o.status?'selected':''}>${s}</option>`).join('')}</select></label>${o.status==='Belum Dibayar'?'<label class="check verification"><input type="checkbox" name="paymentVerified"> Saya sudah memeriksa bukti pembayaran di WhatsApp dan memastikan dana masuk sesuai nominal.</label>':`<p class="badge green">Pembayaran sudah diverifikasi${o.paymentVerifiedAt?' · '+esc(new Date(o.paymentVerifiedAt).toLocaleString('id-ID')):''}</p>`}<label class="field">Tautan hasil (opsional)<input name="resultUrl" type="url" maxlength="2000" value="${esc(o.resultUrl)}"></label><label class="field">Catatan untuk pelanggan<textarea name="adminNote" maxlength="2000">${esc(o.adminNote)}</textarea></label><div id="orderError" class="error" role="alert" tabindex="-1"></div><button class="btn primary" type="submit">Simpan Perubahan</button><p class="tiny muted">Proses Pengerjaan hanya dimulai setelah verifikasi. Selesai dipilih admin setelah pekerjaan selesai.</p></form>`);}
const previousSettingsPage=darkSettingsPage;
function settingsPage(){previousSettingsPage();const form=$('#settingsForm');const section=document.createElement('section');section.className='full qris-admin';section.innerHTML=`<h3 style="font-size:18px;margin-bottom:14px">QRIS Pembayaran</h3><label class="field">Unggah / ganti gambar QRIS<input id="qrisUpload" type="file" accept="image/png,image/jpeg,image/webp"><small>Gunakan QRIS asli merchant. Maks. 1,5 MB; disimpan tanpa kompresi agar kode tetap terbaca.</small></label><label class="field" style="margin-top:16px">Atau URL gambar QRIS HTTPS<input id="qrisUrlInput" type="url" value="${driveRefId(S.admin.settings.qrisImage)?'':esc(S.admin.settings.qrisImage||'')}" placeholder="https://…"></label><div id="qrisAdminPreview" style="margin-top:16px"></div><div class="row wrap" style="margin-top:16px"><button class="btn small" type="button" data-action="removeQris">Hapus QRIS</button>${S.admin.driveFolderUrl?`<a class="btn small" href="${esc(safeUrl(S.admin.driveFolderUrl))}" target="_blank" rel="noopener noreferrer">Buka Folder Media Drive</a>`:''}</div><p class="tiny muted" style="margin-top:12px">Unggahan thumbnail, galeri, logo, dan QRIS disimpan di folder Drive akun deployment. Simpan Pengaturan setelah mengganti QRIS.</p>`;form.insertBefore(section,$('#settingsError'));S.qrisImage=S.admin.settings.qrisImage||'';previewQrisAdmin();}
function previewQrisAdmin(){const el=$('#qrisAdminPreview');if(!el)return;const src=safeUrl(S.qrisImage,true);el.innerHTML=src?`<img src="${esc(src)}" alt="Pratinjau QRIS admin" style="max-width:240px;max-height:330px;object-fit:contain;background:white;padding:12px;border-radius:12px" referrerpolicy="no-referrer">`:'<p class="tiny muted">QRIS belum diatur. Checkout menunggu QRIS dan nomor WhatsApp admin.</p>';scanMedia();}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('File tidak dapat dibaca.'));r.readAsDataURL(file);});}
async function uploadImage(file,kind){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Gunakan PNG, JPG, atau WebP.');if(file.size>5*1024*1024)throw Error('Maksimal 5 MB untuk gambar katalog.');let data;if(kind==='qris'){if(file.size>1500000)throw Error('QRIS maksimal 1,5 MB. Gunakan file asli berukuran lebih kecil agar kode tidak berubah.');data=await fileData(file);}else if(file.size<=1200000)data=await fileData(file);else{const img=await createImageBitmap(file);try{const canvas=document.createElement('canvas');const scale=Math.min(1,1600/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');if(kind!=='logo'){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(img,0,0,canvas.width,canvas.height);data=canvas.toDataURL(kind==='logo'?'image/webp':'image/jpeg',.8);}finally{img.close();}}if(data.length>2100000)throw Error('Gambar masih terlalu besar. Pilih berkas lebih kecil.');const result=await api('uploadMedia',{kind,data,requestId:randomHex()});MEDIA_CACHE.set(result.id,data);return result.ref;}
document.addEventListener('input',e=>{if(e.target.id==='qrisUrlInput'){S.qrisImage=e.target.value.trim();previewQrisAdmin();}});
document.addEventListener('change',async e=>{if(e.target.id!=='qrisUpload'||!e.target.files[0])return;const button=$('#settingsForm button[type=submit]');button.disabled=true;try{S.qrisImage=await uploadImage(e.target.files[0],'qris');$('#qrisUrlInput').value='';previewQrisAdmin();toast('QRIS diunggah ke Drive. Simpan Pengaturan untuk menerbitkan.');}catch(err){$('#settingsError').textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='removeQris'){S.qrisImage='';$('#qrisUrlInput').value='';$('#qrisUpload').value='';previewQrisAdmin();}
else if(b.dataset.action==='zoomQris'){const src=safeUrl(S.settings.qrisImage,true);if(src){const zoom=document.createElement('dialog');zoom.className='dialog';zoom.setAttribute('aria-label','Perbesar QRIS pembayaran');zoom.innerHTML=`<div class="dialoghead"><h2>QRIS Pembayaran</h2><button class="iconbtn" type="button" aria-label="Tutup QRIS">${icon('x')}</button></div><div class="dialogbody"><img class="zoom-image" src="${esc(src)}" alt="QRIS pembayaran dari admin" style="background:white;padding:18px" referrerpolicy="no-referrer"></div>`;document.body.appendChild(zoom);zoom.querySelector('button').addEventListener('click',()=>zoom.close());zoom.addEventListener('close',()=>{zoom.remove();if(b.isConnected)b.focus();});zoom.showModal();scanMedia();}}
else if(b.dataset.action==='payQris'){const o=S.orders?.find(x=>x.id===b.dataset.id);if(o)checkoutSuccess(o);}
else if(b.dataset.action==='sendProof'){const o=S.paymentOrder;const link=whatsappLink(orderMessage(o));if(!link)throw Error('Nomor WhatsApp admin belum diatur.');const win=window.open(link,'_blank','noopener,noreferrer');b.disabled=true;$('#proofFallback').innerHTML=`<p class="tiny muted" style="margin-top:16px">Jika WhatsApp tidak terbuka, <a href="${esc(link)}" target="_blank" rel="noopener noreferrer">buka draft bukti pembayaran di sini</a>. Lampirkan bukti dan tekan Kirim sendiri. Status tetap Belum Dibayar sampai admin memverifikasi.</p>`;try{await api('confirmPayment',{id:o.id});toast('Draft WhatsApp dibuka. Lampirkan bukti; status menunggu verifikasi admin.');}catch(err){$('#proofError').textContent='Draft tersedia, tetapi catatan pembukaan belum tersimpan: '+err.message;}finally{b.disabled=false;}}
}catch(err){toast(err.message);}});
