function help(){legacyHelp();const page=$('#page');page.innerHTML=page.innerHTML.replaceAll('Review Pelanggan','Proses Pengerjaan').replace('kirim brief, lalu ikuti instruksi pembayaran.','simpan pesanan, bayar QRIS, lalu kirim bukti melalui WhatsApp.').replace('review hasil dan ajukan revisi bila perlu.','buka hasil dan ajukan revisi bila perlu.');const intro=document.createElement('section');intro.className='panel';intro.style.marginBottom='24px';intro.innerHTML='<h2 style="font-size:20px;margin-bottom:14px">Pembayaran QRIS & Status Pesanan</h2><p class="tiny muted">Pilih jasa dan paket, masuk saat checkout, simpan pesanan, lalu bayar melalui QRIS yang disediakan admin. Tekan Kirim Bukti Pembayaran, lampirkan screenshot transfer sendiri di WhatsApp, dan tekan Kirim.</p><div class="row wrap"><span class="badge orange">1 · Belum Dibayar</span><span class="badge">2 · Proses Pengerjaan</span><span class="badge green">3 · Selesai</span></div><p class="tiny muted" style="margin-top:16px">Status tetap Belum Dibayar selama menunggu pemeriksaan bukti. Hanya admin yang mengubah status setelah memastikan dana masuk, lalu menyelesaikan pekerjaan. Mengirim bukti tidak memverifikasi transaksi secara otomatis.</p>';page.prepend(intro);}
/* JASAhub: scroll after opening a catalog service, without changing CSS/API. */
(() => {
  if (window.JASAhubCatalogScroll) return;
  let frame = 0;
  function scrollToTop() {
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
        document.querySelector('main')?.focus({ preventScroll: true });
        window.scrollTo({ top: 0, left: 0, behavior: reduced ? 'instant' : 'smooth' });
      });
    });
  }
  document.addEventListener('click', event => {
    if (!(event.target instanceof Element) || event.defaultPrevented || event.button > 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
    const trigger = event.target.closest('[data-action="detail"], a[href^="#service/"]');
    if (trigger) { scrollToTop(); return; }
    const card = event.target.closest('article.service');
    if (!card || event.target.closest('a,button,input,textarea,select,label,[contenteditable="true"]') || window.getSelection()?.toString()) return;
    // Reuse the existing button handler: navigation, selected service, and packages remain intact.
    const button = card.querySelector('[data-action="detail"]');
    if (button && !button.disabled) button.click();
  });
  window.addEventListener('hashchange', () => {
    if (location.hash.startsWith('#service/')) scrollToTop();
  });
  window.JASAhubCatalogScroll = { scrollToTop };
})();


/* Persist only the server-issued token, never credentials or private order data. */
function readSessionToken(){try{return localStorage.getItem('jh:session:'+CONFIG.API_URL)||sessionStorage.getItem('jh_token')||'';}catch(_){try{return sessionStorage.getItem('jh_token')||'';}catch(_){return '';}}}
function persistSessionToken(token){try{if(token)localStorage.setItem('jh:session:'+CONFIG.API_URL,token);else localStorage.removeItem('jh:session:'+CONFIG.API_URL);}catch(_){}try{if(token)sessionStorage.setItem('jh_token',token);else sessionStorage.removeItem('jh_token');}catch(_){}}
function sessionRejected(error){return /sesi berakhir|silakan masuk terlebih dahulu|akun tidak aktif/i.test(error.message||'');}
async function restoreAccount(){try{S.user=await api('me');persistSessionToken(S.token);S.sessionIssue='';}catch(error){if(sessionRejected(error)){S.token='';S.user=null;persistSessionToken('');}else{S.sessionIssue=error.message;toast('Koneksi akun terganggu. Sesi tetap disimpan; tekan Coba Lagi untuk menyambungkan kembali.');}}}
function catalogSkeleton(){return `<section class="catalog-skeleton" aria-busy="true" aria-label="Memuat katalog"><p class="loading-label" role="status">Memuat layanan JASAhub…</p><div class="skeleton skeleton-hero" aria-hidden="true"></div><div class="grid" aria-hidden="true">${Array.from({length:6},()=>'<div class="skeleton-card"><div class="skeleton skeleton-picture"></div><div class="skeleton skeleton-line"></div><div class="skeleton skeleton-line short"></div><div class="skeleton skeleton-line"></div></div>').join('')}</div></section>`;}
function updateMobileChrome(){const hash=location.hash.slice(1)||'catalog';const page=hash.split('/')[0];const active=page==='service'||hash==='catalog/all'?'catalog':page==='catalog'?'home':page==='orders'?'orders':page==='profile'?'profile':'';$('#mobileBottomNav').innerHTML=[['home','#catalog','home','Beranda'],['catalog','#catalog/all','grid','Katalog'],['orders','#orders','bag','Pesanan'],['profile','#profile','user','Akun']].map(([key,href,svg,label])=>`<a href="${href}" class="${key===active?'active':''}" ${key===active?'aria-current="page"':''}>${icon(svg,22)}<span>${label}</span></a>`).join('');const dock=$('#checkoutDock'),show=page==='service'&&!!S.selected&&!!$('#packageCards');dock.hidden=!show;document.body.classList.toggle('has-checkout',show);if(show){const x=S.package;dock.innerHTML=`<div class="dock-summary"><small>Paket ${esc(x.name)} · ${Number(x.days)} hari</small><strong>${rupiah(x.price)}</strong></div><button class="btn primary" data-action="checkout">Lanjut Checkout ${icon('arrow',16)}</button>`;}}
