orderCard=function(o){const result=safeUrl(o.resultUrl);const material=safeUrl(o.materialUrl);return `<article class="ordercard compact-order"><div class="row spread wrap"><span class="tiny muted">${esc(o.id)}</span><span class="badge ${o.status==='Selesai'?'green':o.status==='Belum Dibayar'?'orange':''}">${esc(o.status)}</span></div><h3>${esc(o.title)}</h3><p class="tiny muted">Paket ${esc(o.packageName||'Basic')}</p><div class="order-summary"><span>Deadline <strong>${esc(o.deadline)}</strong></span><strong>${rupiah(o.price)}</strong></div><div class="orderactions">${o.status==='Belum Dibayar'?`<button class="btn small" data-action="payQris" data-id="${esc(o.id)}">${icon('wallet',16)} Lihat QRIS</button><button class="btn primary small" data-action="proofFromOrder" data-id="${esc(o.id)}">${icon('message',16)} Kirim Bukti</button>`:''}${result?`<a class="btn primary small" href="${esc(result)}" target="_blank" rel="noopener noreferrer">${icon('doc',16)} Unduh Hasil</a>`:''}${o.status==='Proses Pengerjaan'&&result&&Number(o.revisions)>0?`<button class="btn small" data-action="revision" data-id="${esc(o.id)}">Minta Revisi</button>`:''}</div><details><summary>Detail pesanan</summary><div class="orderbody"><div><span class="label">Kebutuhan</span><p>${esc(o.brief)}</p>${o.customerNote?`<p class="tiny muted">Catatan: ${esc(o.customerNote)}</p>`:''}${material?`<a class="tiny" href="${esc(material)}" target="_blank" rel="noopener noreferrer">Buka bahan</a>`:''}${o.adminNote?`<p><strong>Catatan admin:</strong><br>${esc(o.adminNote)}</p>`:''}</div><div><span class="label">Informasi</span><p>Sisa revisi ${Number(o.revisions)||0}</p><p class="tiny muted">Dibuat ${esc(new Date(o.createdAt).toLocaleDateString('id-ID'))}</p>${o.paymentVerifiedAt?`<p class="tiny muted">Pembayaran diverifikasi ${esc(new Date(o.paymentVerifiedAt).toLocaleString('id-ID'))}</p>`:(o.status==='Belum Dibayar'?'<p class="tiny muted">Menunggu verifikasi pembayaran oleh admin.</p>':'')}</div></div></details></article>`;};
ordersPage=async function(version){if(!S.user){$('#page').innerHTML=`<section class="empty"><h1 style="font-size:24px">Pesanan Saya</h1><p>${S.token&&S.sessionIssue?'Sesi masih disimpan. Sambungkan kembali untuk melihat pesanan.':'Masuk untuk melihat pesanan dan hasil pengerjaan.'}</p><button class="btn primary" data-action="${S.token&&S.sessionIssue?'retryAccount':'auth'}" data-mode="login">${S.token&&S.sessionIssue?'Coba Lagi':'Masuk'}</button></section>`;return;}$('#page').innerHTML=busy();try{const orders=await api('orders');if(version!==S.routeVersion)return;S.orders=orders;const active=orders.filter(o=>o.status!=='Selesai').sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));const done=orders.filter(o=>o.status==='Selesai').sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));$('#page').innerHTML=`<div class="sectionhead"><div><h1 style="font-size:25px">Pesanan Saya</h1><p>${active.length} aktif · ${done.length} selesai</p></div><button class="btn small" data-action="refresh">${icon('refresh',16)} Muat ulang</button></div>${orders.length?`<h2 class="orders-group-title">Pesanan aktif <span class="orders-count">(${active.length})</span></h2><div class="stack">${active.map(orderCard).join('')||'<div class="panel tiny muted">Tidak ada pesanan aktif.</div>'}</div>${done.length?`<h2 class="orders-group-title">Pesanan selesai <span class="orders-count">(${done.length})</span></h2><div class="stack">${done.map(orderCard).join('')}</div>`:''}`:'<section class="empty"><h2>Belum ada pesanan</h2><p>Temukan layanan yang sesuai kebutuhanmu.</p><a href="#catalog/all" class="btn primary">Jelajahi Jasa</a></section>'}`;}catch(error){if(version===S.routeVersion)pageError(error);}};
renderAdminOrders=function(){const d=S.admin;const filtered=d.orders.filter(o=>{const u=d.customers.find(x=>x.id===o.userId);return (S.adminStatus==='all'||o.status===S.adminStatus)&&[o.id,u?.name,u?.phone,o.title,o.packageName].join(' ').toLowerCase().includes(S.adminSearch.toLowerCase());}).sort((a,b)=>Number(a.status==='Selesai')-Number(b.status==='Selesai')||Date.parse(b.createdAt)-Date.parse(a.createdAt));$('#adminOrderList').innerHTML=filtered.map(o=>{const u=d.customers.find(x=>x.id===o.userId);return `<article class="adminitem admin-order-card"><div class="admin-order-summary"><div class="row spread wrap"><span class="tiny muted">${esc(o.id)}</span><span class="badge ${o.status==='Selesai'?'green':o.status==='Belum Dibayar'?'orange':''}">${esc(o.status)}</span></div><h3>${esc(o.title)}</h3><p>${esc(u?.name||o.userId)} · Paket ${esc(o.packageName||'Basic')}</p><p>Deadline ${esc(o.deadline)}</p><div class="admin-order-bottom"><strong>${rupiah(o.price)}</strong><button class="btn small" data-action="editOrder" data-id="${esc(o.id)}">Buka Detail ${icon('arrow',16)}</button></div></div></article>`;}).join('')||'<section class="empty"><h3>Tidak ada pesanan yang cocok</h3><p>Ubah pencarian atau filter status.</p></section>';};
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='retryAccount'){b.disabled=true;try{await restoreAccount();topbar();await route();}finally{if(b.isConnected)b.disabled=false;}}if(b.dataset.action==='proofFromOrder'){const o=S.orders?.find(x=>x.id===b.dataset.id);if(!o)return;checkoutSuccess(o);$('#waMessage')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});}});
window.addEventListener('storage',async event=>{if(event.key!=='jh:session:'+CONFIG.API_URL)return;S.token=event.newValue||'';S.user=null;S.admin=null;if(S.token)await restoreAccount();else persistSessionToken('');topbar();await route();});

